window.POETRY_REGISTER("v4-poems-645.js",{"records":[["夜半开还阖，天心在一花。\n香从元气出，独自作春华。",""],["独坐忘清昼，香微易入神。\n不须开万蕊，已得太和真。",""],["欲折枝高出，烟凝望欲空。\n光生三径月，香作一林风。",""],["天寒香更发，花定不知寒。\n多谢风兼雪，吹花透肺肝。",""],["花开罢读书，相对一冬馀。\n香使春风暖，氤氲满太虚。",""],["相看忘语默，心以暗香通。\n不忍扃扉卧，迟回夜月中。",""],["花以香为教，闻香每发机。\n春风如有意，吹入客心微。",""],["花开当静者，无语只馨香。\n神契谁能似，依依水一方。",""],["夜半春风转，惊梅此水涯。\n吹开人不识，一一是心华。",""],["香使神清爽，先春为我开。\n微风吹不去，香自返魂来。",""],["香中无所有，心忽以香生。\n一点为香母，氤氲不可名。",""],["春光才一点，已觉早梅清。\n不是香含吐，安知最有情。",""],["夜来庭砌上，使我月明多。\n一片如冰雪，流光奈尔何。",""],["香自梅花始，春从子夜回。\n坐深烟影下，心与蕊争开。",""],["香自暗中生，消人寂寞情。\n闻香难入定，徙倚到深更。",""],["白金乃人肉，黄金乃人膏。\n使君非豺虎，为政何腥臊。",""],["珠皆泪所成，不必鲛人泣。\n三斛买蛮娥，馀以求大邑。",""],["初捕金五千，再捕金一万。\n金尽鬻妻孥，以为府君饭。",""],["东莞有廉泉，长官何不酌。\n府中诸吏胥，岂可为囊橐。",""],["动则勒长夫，一夫金十二。\n长吏亦受欺，金来仅得四。",""],["小府为鱼肉，大府为庖厨。\n金多免刀俎，且复得安居。",""],["金为莲叶珠，珠多叶倾覆。\n使君勿爱金，莲茎自矗矗。",""],["黄金自吴来，精者十三倒。\n上官争买时，白银不言好。",""],["𫖯有十千拾，仰有五万取。\n作使诸豪奴，官大好行贾。","頫有十千拾，仰有五万取。\n作使诸豪奴，官大好行贾。"],["长官尽奸富，为恶未渠央。\n各使金如粟，各使马如羊。",""],["纨扇先秋叶，徒怀明月新。\n自怜妾命薄，不敢妒他人。",""],["山翠晴犹湿，空蒙翠作烟。\n天门何所有，倒挂一晴川。","山翠晴犹湿，空濛翠作烟。\n天门何所有，倒挂一晴川。"],["清啸复鸣弦，楼开太华边。\n风吹玉女影，朝夕在窗前。",""],["一夕林中啸，秋声处处悲。\n天边有鸿雁，相应月斜时。",""],["愿君为罗浮，不愿为太华。\n罗浮合不离，高为南岳亚。",""],["太华一山分，其东为雷首。\n中有黄河流，波涛作雷吼。",""],["浮山嫁与罗，不复随风波。\n罗得浮山大，峰馀四百多。",""],["巨灵诚不仁，太华擘为两。\n可怜首阳山，不得接秦壤。",""],["今日汉家子，谁非粪上英。\n琵琶弹马上，哀怨莫分明。",""],["玉貌同秋草，青青岂得长。\n已安殊类久，妻子亦何伤。",""],["霜雪欺玄首，秋来见几丝。\n多惭明镜照，正是始衰时。",""],["初日照金沙，溪光一道斜。\n流霞随水出，灼灼似桃花。",""],["可怜梧树枝，孤凤日相思。\n亦有瑶台月，含光欲赠谁。",""],["春水没湖堤，舟平与草齐。\n荷花都解语，莫向若耶溪。",""],["一片耶溪水，佳人拂镜过。\n至今生菡萏，香比洞庭多。",""],["旧业多花药，归来春正妍。\n罗浮峰四百，一日一峰眠。",""],["一水穿深竹，孤舟荡晚风。\n但沿明月去，忽与大江通。",""],["何代葬神仙，朱明深洞边。\n遗衣化蝴蝶，五色似霞鲜。",""],["岁岁天山雁，衔书不到家。\n君看陇头雪，应念雒阳花。",""],["二水交苕霅，流从天目来。\n白鸥飞不尽，争拂酒船回。",""],["岁暮阳关路，愁君匹马行。\n离心似春草，一夕雪中生。",""],["荔支犹未熟，稚子望秋蝉。\n白雨朝来落，千株红欲然。",""],["黄河春冻解，太华晓云晴。\n匹马蒲关渡，中流津吏迎。",""],["梅子兼樱笋，春来玄墓多。\n家家太湖水，日日白鸥过。",""],["窈窕台关路，苍松夹岭斜。\n鹧鸪蛮女曲，茉莉汉臣花。",""],["地下多吾友，皆为殇鬼雄。\n夜来梦雪窦，长啸战场中。",""],["巢许非吾志，林泉偶自闲。\n如逢尧舜禅，岂肯入箕山。","巢许非吾志，林泉偶自閒。\n如逢尧舜禅，岂肯入箕山。"],["阿卿美容仪，粉白不去手。\n忆昔交欢时，芙蓉始行藕。",""],["虚堂坐无寥，思子不能饭。\n拳拳饥渴心，谗口愁滋蔓。",""],["可怜御沟水，一旦东以西。\n愿君弃小怨，出入还提携。",""],["种树必琅玕，养禽须翡翠。\n君子结交心，兢兢畏非类。",""],["妾作下湖莼，郎作上湖莲。\n莲衣易飘落，莼丝长缠绵。",""],["槿花能爱老，开向白头人。\n那得还童术，为君留暮春。",""],["芙蓉三日醉，菡萏一秋香。\n白首难忘汝，相依此瘴乡。",""],["佛桑花上花，红者如朝霞。\n自可成春酒，无烦采日华。",""],["枝枝白间黄，时至自芬芳。\n挹露采盈手，怜君此晚香。",""],["花萎亦不零，叶黄亦不落。\n天与岁寒姿，霜露从相薄。",""],["苦薏与甘菊，芳馨自为伍。\n同是岁寒花，其中有甘苦。",""],["天南霜雪少，花事总无穷。\n秋发多梅树，春开是菊丛。",""],["花干似委蜕，朵朵含坚冰。\n不忍辞根蒂，春寒亦自胜。","花乾似委蜕，朵朵含坚冰。\n不忍辞根蒂，春寒亦自胜。"],["已食沉水烟，复藏双翅内。\n时放烟氤氲，帏中香久在。",""],["黑润与黄沉，持薰倒挂鸟。\n不教双翅间，收得香烟少。",""],["一唇有数珠，大小相连缀。\n采珠乘月圆，扬帆入龙穴。",""],["水淡珠多白，水咸珠多黄。\n月光化为水，来养明月珰。",""],["娶女得珠娘，自解孕明月。\n与卿若蟾兔，长在太阴窟。",""],["生长珠池旁，食珠如食米。\n日夕剖神胎，珠肉荐芳醴。",""],["儿女抱珠筐，细珠弃不取。\n珠母肉微红，色似海棠乳。",""],["珠母当秋孕，精华得月全。\n明珠无大小，都在口唇边。",""],["儿小方垂鬌，能争掌上梨。\n双双初学语，恰似乳莺啼。",""],["蒿蒌沦为齑，吴酸古所尚。\n甘美可招魂，更有梅花酿。",""],["烟雨催寒食，江南又暮春。\n可怜三月草，看尽六朝人。",""],["自与台城别，艰难觅故君。\n年年寒食日，望断孝陵云。",""],["吹笛关河夜，衣裳清露滋。\n谁能见秋月，不起故山思。",""],["伯鸾无至友，相与只高恢。\n可念平生好，遥寻杵臼来。",""],["昔过紫荆关，尝饮易州酒。\n滑辣胜葡萄，至今难上口。",""],["岩林长啸久，人道古遗狂。\n枕仗当明月，猿裘一半霜。",""],["贼马千百群，就颈吸人血。\n一马吸一人，血多流不绝。",""],["马饮人血肥，生臕毛润泽。\n杀人但取血，肌肉成糟粕。",""],["暮天稍晴霁，雨气白成云。\n月出争残日，林光两不分。",""],["岭海炎蒸甚，秋分气始凉。\n无劳弃𫄨绤，此地少风霜。","岭海炎蒸甚，秋分气始凉。\n无劳弃絺绤，此地少风霜。"],["季夏边草衰，胡鹰方学习。\n角弓得风劲，射猎向马邑。",""],["南朝汉儿好，一一用交鎗。\n短兵入弓矢，我尽失所长。",""],["哑哑枝上乌，有母不得餔。\n可怜八九子，日夜求雕胡。","哑哑枝上乌，有母不得餔。\n可怜八九子，日夜求彫胡。"],["枯杨能生荑，卿乃不言好。\n不如朱槿花，姿容能爱老。",""],["橘柚炎天物，霜时熟更红。\n骚人曾颂汝，香在九章中。",""],["方丈多花发，秋深恰似春。\n从师分数种，来伴坐愁人。",""],["最是芙蓉好，枝枝拂镜斜。\n幸无头上雪，不怕笑人花。",""],["菊花先爱黄，次乃及红白。\n黄者味逾甘，落英犹可惜。",""],["鸡冠大一尺，朵朵红葳蕤。\n花头虽太重，霜压不曾垂。",""],["花中谁得似，长是老来红。\n折取当明镜，衰颜欲与同。",""],["立冬前未冷，已是放梅时。\n一朵开方半，人从定里知。",""],["桂树凌寒开，香多嫌酷烈。\n不若早梅清，平生在冰雪。",""],["先开避冰雪，岂是南枝心。\n欲与黄花并，芬芳作一林。",""],["一枝穿海棠，未开人不觉。\n寄语枝间禽，蕊香休乱啄。",""],["花爱仙人好，相将隐玉壶。\n不知花主意，肯割数枝无。",""],["一弹一鹞子，一曲一鹌鹑。\n忙杀铁桥老，童儿绕锦茵。",""],["墨花风雨乱，写出尽䅉兰。\n似有兰膏滴，香含清露寒。","墨花风雨乱，写出尽稏兰。\n似有兰膏滴，香含清露寒。"],["小小黄山笋，移来画册中。\n英州那有此，尺寸亦华嵩。",""],["十五乘潮女，清歌过若耶。\n因生西子地，颜色艳如花。",""],["大奴调鹞子，小奴调鹌鹑。\n中奴持弹弓，游戏出龙津。",""],["马肥不食草，啖以园中花。\n寒薰马粪香，渴饮马乳茶。",""],["沉香为马栈，翠羽为马房。\n马饮葡萄酒，旁多红粉妆。",""],["番獒高五尺，酣卧多罗绒。\n紫貂为裀褥，白貂为屏风。",""],["炕用蔚州煤，墙衣高丽茧。\n羊酪入酒香，馀肉肥鹰犬。",""],["小小红毛兔，冬肥及野鸡。\n连朝亲射得，跃马黑河西。",""],["郎食槟榔花，胜于甜娘酒。\n槟榔花醉人，且可红唇口。",""],["海南绣面女，爱食槟榔青。\n槟榔成枣子，醉杀两娉婷。",""],["畲客石为田，田肥宜石粪。\n英州石太多，燔石无人问。",""],["火烧土膏暖，阳气发畲田。\n尽斩阴阳木，斜禾种绝巅。",""],["白衣山子好，山旱种乘春。\n拨雪烧畲熟，禾生火粒新。",""],["一峰一瀑布，高者是黄岩。\n雨过人争望，湖边宿片帆。",""],["随风泉作态，欲落故盘旋。\n马尾飘天半，光摇双剑边。",""],["瀑布不肯斜，条条如匹练。\n安得并州刀，剪取为纨扇。",""],["谁将彭蠡水，吸上乱峰间。\n化作泉千道，奔飞响一山。",""],["犹嫌千仞瀑，飞不到舟边。\n安得天风起，吹来洒昼眠。",""],["菜中惟水葵，逐水性甘滑。\n叶少多紫茎，浮沉不易拔。",""],["水深莼茎肥，水浅莼茎瘠。\n四月泖湖莼，紫者堪留客。",""],["谁知瀑布里，亦有一人家。\n多谢溪边鹿，来寻不食花。",""],["门外水帘垂，天风不肯吹。\n吹开见石上，仙老不知谁。",""],["西日尚未落，已闻车声来。\n美人卷帘待，羊至亦徘徊。","西日尚未落，已闻车声来。\n美人捲帘待，羊至亦徘徊。"],["多谢水精盐，能使羊欢喜。\n羊也亦多情，以妾颜色美。",""],["羚羊古峡口，南转水岩开。\n西洞青花好，君贻一片来。",""],["紫云凝作膏，氤氲气尝湿。\n割向九渊中，持归真宰泣。",""],["纯紫似羊肝，半含蕉叶白。\n真气作泉流，墨花长润泽。",""],["东洞火痕多，温柔如水玉。\n秀色生文姿，为君日三浴。",""],["流莺无事极，啼遍落花前。\n笑杀垂垂柳，临风只爱眠。",""],["日暖人多梦，春来物有情。\n林花知客恨，开落不分明。",""],["兰吐宜清夜，香惟风露知。\n露华多在蕊，风势不成枝。",""],["风露夜有香，知是幽兰吐。\n山人每不眠，闻香得深悟。",""],["幽兰开向夜，风露自成香。\n欲得兰膏饮，穿林至石梁。",""],["松枝多变化，怪绝似诸峰。\n疑尔黄山客，前身亦一松。",""],["松与峰多怪，盘旋势万重。\n有时蝉蜕去，一半化为峰。",""],["三十六峰外，疑皆松所成。\n巨灵多变怪，一一本无情。",""],["蕉叶何尝落，干时可作书。\n绕庭三十树，人道绿天如。","蕉叶何尝落，乾时可作书。\n绕庭三十树，人道绿天如。"],["黄山携一笋，画出似奇峰。\n怪石平生好，于兹得次宗。",""],["折尽东西柳，销魂自汉时。\n人言枝上鸟，总是一相思。",""],["笔削吾何倦，春秋以没身。\n诸侯多史记，采取托何人。",""],["妆罢下阶行，正见春流满。\n叹息一池中，菱寒芡独暖。",""],["妾似蜀葵花，叶多能自卫。\n嗟尔太阳光，曾不照根蒂。",""],["与君若潇湘，二水长相合。\n慎勿向荆州，从戎衣韎韐。",""],["君似洞庭湖，风波常倏忽。\n贱妾学君山，随流终不没。",""],["不助五诸侯，蛮中窃为帝。\n谁知黄屋中，乃是一椎髻。",""],["惊马吹悲篥，边风助苦声。\n城南有思妇，梦里听分明。",""],["珠斗城边客，诗才丽绝伦。\n同心梅与李，共作上林春。",""],["方春辞涨海，未雪至炎州。\n南国无人射，菰芦最可留。",""],["江流知几曲，尽是荔枝湾。\n一艇潮凫似，随潮日往还。",""],["自来烟雨景，最是大通多。\n两浆迟迟度，江风未起波。",""],["江至鹅潭阔，春来益渺茫。\n中流波浪起，愁杀捕鱼郎。",""],["可怜秋海棠，春暮已争开。\n金丝与西府，并作一香来。",""],["丫角半垂丝，蛮花大于髻。\n双行桃树间，婀娜才五岁。",""],["开似未开时，芬馨不自知。\n微风吹不远，清梦最相宜。",""],["岂必花全吐，馨香已绝人。\n真兰元一朵，不忍摘当春。",""],["爱听疏雨滴，窗外作蕉林。\n静久无魂梦，秋来彻夜吟。",""],["山堂雷雨夜，独坐只焚香。\n香可清神爽，通宵一气长。",""],["始知元气大，为水竟包天。\n一片洋船落，微茫在暮烟。",""],["有天皆化水，无月不生潮。\n万里长堤外，波涛极沃焦。",""],["日出当中夜，红轮十丈馀。\n海波烧尽赤，掩映是扶胥。",""],["舒卷因风雨，芭蕉亦有心。\n秋来无一事，叶叶写新吟。",""],["水气含云白，山光吐雨青。\n帆低争拂树，过我浣花亭。",""],["雨随云气去，雷逐电光来。\n为爱秋凉入，轩窗面面开。",""],["先秋林叶落，片片作声干。\n坐久生明月，苔花不觉寒。","先秋林叶落，片片作声乾。\n坐久生明月，苔花不觉寒。"],["霜凋采菰米，为饭何香脆。\n更得鲈鱼羹，可以娱荒岁。",""],["溪鸣知水涨，木落觉山空。\n野鹿闲相过，黄花食一丛。","溪鸣知水涨，木落觉山空。\n野鹿閒相过，黄花食一丛。"],["暮天晴遂定，秋使月明多。\n最爱云光薄，微微拂绛河。",""],["秋人易不眠，中夜起长叹。\n不若能鸣鸡，犹知天欲旦。",""],["隔浦如烟雾，那知是月明。\n凄凉林木外，一叶亦心惊。",""],["雨含黄口气，野外半阴晴。\n处处陂塘水，秋来一夜平。",""],["紫蟹得霜肥，衔禾上钓矶。\n闲垂兄弟钓，更得白鱼归。","紫蟹得霜肥，衔禾上钓矶。\n閒垂兄弟钓，更得白鱼归。"],["明月化为水，微茫入太清。\n坐随河汉落，一啸至天明。",""],["城南休骋望，秋色未分明。\n云作穹庐气，风为觱篥声。",""],["暮天俄惨淡，海作飏潮风。\n吹水来高树，疏疏雨点同。",""],["平生何所食，命寄首山薇。\n采义劳妻子，无端此乐饥。",""],["最恨乔松上，无端是兔丝。\n缠绵枝与叶，直至后凋时。",""],["一片空蒙里，泉飞似白云。\n随风将落叶，总作雨纷纷。","一片空濛里，泉飞似白云。\n随风将落叶，总作雨纷纷。"],["犹乘五十时，多学母为师。\n膝下如南面，无令游子知。",""],["白芋持为粉，良姜用作齑。\n雌雄多笋竹，一夜出林齐。",""],["生憎蕉叶大，受得雨声多。\n不寐思天曙，明灯在薜萝。",""],["阶下多孩菊，庭前复女兰。\n汲泉频灌溉，持作老亲欢。",""],["璅?羹清绝，河豚美在肝。\n养亲多海错，不用采芳兰。",""],["龙江多美酒，春白与秋红。\n注以离支液，香生玉盏中。",""],["海鱼称第一，䲝与马膏鲫。\n疍女持相赠，烹来一室香。","海鱼称第一，䱽与马膏鲫。\n疍女持相赠，烹来一室香。"],["四星明狗国，犹在斗魁东。\n天象何时变，吾兹怨道穷。",""],["一阳生小雪，梅蕊已纷纷。\n梦里知开落，香多竟不闻。",""],["凉蝉饮风露，流响满空林。\n独自为高洁，应非吾子心。",""],["坑田肥美甚，种得芋渠多。\n稚子喧争好，秋来未刈禾。",""],["香好消魂梦，氤氲至夜分。\n馀烟飞不尽，凝作半床云。",""],["毛茶自乐昌，五内尽清凉。\n屋角新泉水，微含石乳香。",""],["蛮瓜争络树，梨实共垂垂。\n未忍除花架，霜风任倒吹。",""],["阶叶飞难远，依依故树边。\n朝来含白露，知是泪痕鲜。",""],["朵朵供朝饮，兰膏是露华。\n秋来无肺病，不用更餐霞。",""],["何处忘人世，平生此石床。\n秋来难出户，恐负菊花香。",""],["边人冬更猎，往往得山熊。\n雪点貂房白，冰凝肉酪红。",""],["夜猴探百尺，偏得兔儿多。\n围猎真吾乐，朝朝逾黑河。","夜猴探百尺，偏得兔儿多。\n围猎真吾乐，朝朝踰黑河。"],["白鹭下沮洳，无心亦在鱼。\n怜君最孤洁，生长水芙蕖。",""],["海日忽沉沉，云含雨气阴。\n通天一道水，吹作瀑花侵。",""],["云边风路小，雨外日光微。\n最惜横江石，无人作钓矶。",""],["花摇知白鹭，水落见红螺。\n一片萧疏雨，声先到芰荷。",""],["双桨逆风潮，心飞不觉遥。\n送君无一语，呜咽是南朝。",""],["水声何潺湲，似与梦魂语。\n愁君一片帆，明夕宿何处。",""],["几载为闲吏，何曾可代农。\n君前多袒裼，柳下不须恭。","几载为閒吏，何曾可代农。\n君前多袒裼，柳下不须恭。"],["频年赴京阙，讵念使臣劳。\n万里持甘毳，亲年日已高。",""],["且喜台关上，梅花不笑人。\n摩娑古松树，十见老龙鳞。",""],["寡过期中岁，人人亦可师。\n君行苦离索，怅望复来时。",""],["一水细通潮，帆低屡过桥。\n阴阴榕影下，渔父不相招。",""],["片雨从西至，开门爽气侵。\n蝉声似溪水，流入野人心。",""],["霜肥螺有柱，月满蟹多黄。\n一棹将童子，遥遥至海塘。",""],["风俗河豚会，秋来乐事多。\n乘潮下生钓，滥口峭帆过。",""],["花中藏跳白，出没少鱼惊。\n向夕鸣榔去，知予是月明。",""],["水乡鱼蟹贱，吾亦事投竿。\n日夕坐盘石，鹭鸶相与寒。",""],["天生屯女子，五十尚红颜。\n不字盘桓甚，金夫未敢攀。",""],["十年坤数尽，辛苦一阳来。\n此际成婚媾，同将草昧开。",""],["夜夜怀明发，先公梦寐劳。\n儿孤从少小，泪已尽莪蒿。",""],["多难凭吾父，提携在梦中。\n此身能老大，不敢恨途穷。",""],["肤发今如此，那能不辱亲。\n梦中长痛哭，惭愧白华身。",""],["五旬今有二，多父一年馀。\n不死如闻道，应能续易书。",""],["妾身不随波，岂必长绳系。\n所虑黄口儿，一去无根蒂。",""],["可怜双美人，慷慨辞君掌。\n沉珠在井中，化为明月上。",""],["清浅西南潭，白波跳霜雪。\n一片秋光寒，谁知是明月。",""],["松露鹤边滴，清冷满石床。\n梦中惊是月，起视白如霜。",""],["碧玉楼中客，无弦一素琴。\n泠然林木外，太古有馀音。",""],["玉琴长寂寂，神与至人期。\n心外无山水，高深只自知。",""],["秋声空外起，一叶亦萧萧。\n吹我鸣琴去，元音满寂寥。",""],["兰草不知名，香含朝露清。\n花长休出叶，岁晏忌孤荣。",""],["幸与蘼芜并，无花亦自芳。\n美人相忆苦，日夕澧川阳。",""],["花叶虽相似，青青有本心。\n亦知霜雪苦，不忍负空林。",""],["月出雨犹滴，微光似在林。\n虫寒声渐小，不忍到愁心。",""],["蟋蟀寒相语，声声有所思。\n思君似初月，相照未多时。",""],["白云不出户，为我含精华。\n所恐风吹去，离离成海霞。",""],["芙蓉白复红，向暮解还童。\n更拒秋霜甚，凝妆在月中。",""],["猗彼幽兰花，春黄而秋紫。\n颜色能随时，所以媚君子。",""],["花叶皆有香，乃可持为佩。\n幽幽君子心，非兰无所爱。",""],["愿君似芙蓉，不食犹可衣。\n芙蓉且有实，一一含霜肥。",""],["愿君如山丹，花红至百日。\n红尽变为黄，犹作纯金质。",""],["愿君似茨菰，一乳十馀子。\n心心向太阳，岁寒花愈美。",""],["愿君若琼木，一身作五香。\n朱火欲尽时，芳气犹飘飏。",""],["甘蕉经雨后，叶叶有新心。\n舒卷无人见，萧疏又一林。",""],["佳色朝来变，微红似带霜。\n但令开满径，何必值重阳。",""],["生意怜春草，油油是我心。\n穿冰才一寸，芳气已盈襟。",""],["又见梅花发，枝枝影向西。\n可怜千万片，飞不到潜溪。",""],["红翠双入帘，知自罗浮至。\n口衔麻姑书，催我营春事。",""],["春已满浮丘，花开多异色。\n生憎小凤凰，向我花上食。",""],["舟浮香溪来，是我餐霞友。\n小女采荼蘼，已泛长春酒。",""],["林鸟喜人归，声声在竹扉。\n花含大小笑，笑客食春薇。",""],["苦瓜君子菜，义不食邪蒿。\n日夕林塘畔，毋辞抱瓮劳。",""],["阴尽天无雪，阳生地有雷。\n黄莺一二啭，已使早梅开。",""],["林深晴日少，天在白云中。\n水气多为雨，山光直似空。",""],["鱼脍宜生酒，餐来最益人。\n临溪亲举网，及此一阳春。",""],["门对先公墓，松楸日夕看。\n无田愁薄祭，凄怆一春盘。",""],["负杖还墟落，韶光正及春。\n涧花欣有主，山鸟喜无人。",""],["未有疗饥物，芝华奈尽何。\n白头孀凤老，黄口乳莺多。",""],["幽幽涧底兰，花叶愁枯槁。\n不及尔青蒿，春阳能得早。",""],["母竹春多笋，新篁十日齐。\n箨龙谁忍斸，留荫白云溪。",""],["东家复有春，墙上一枝新。\n未得春风吐，夭夭已笑人。",""],["一朵风兰好，空生不作趺。\n自来根本异，宁待露沾濡。",""],["泉飘百丈带，曲折下流溪。\n车水村村急，春苗莳未齐。",""],["垂柳与垂杨，枝条有短长。\n柳长杨短短，一体似鸳鸯。",""],["风流水杨柳，宜水复宜风。\n莫即为花絮，飘飏西复东。",""],["菱花背日寒，芡花向日暖。\n同是水中根，为心有长短。",""],["有美云堂树，冬生翠负霜。\n少阴精自固，名以冻青香。",""],["日月同一光，男女同一性。\n君不爱离居，早归共鸾镜。",""],["在北为苍鹰，在南为鹞子。\n秋来奋羽毛，一击辄千里。",""],["儿时射鸟鼠，稍长射狐兔。\n生长牛羊中，肥白亦如瓠。",""],["壮者食肥美，老者食其馀。\n黄羊与野马，毛血腥衣裾。",""],["箕踞而反言，佯为蛮种落。\n袍帽尽鼲貂，拦街弄弦索。",""],["自古汉和蕃，不闻蕃和汉。\n汉儿一向眠，自致南朝乱。",""],["君在黄山口，桃花十里长。\n不知溪上水，流得几峰香。",""],["未开先食蕾，虫细若飞丝。\n叶底粉如雪，香宜月上时。",""],["欲花先摘叶，叶少始花多。\n向夕沾人气，香如膏沐何。",""],["紫芝华正秀，黄鹄翼还开。\n绮皓诚儒者，何曾嫚骂来。",""],["西汉崇儒术，功推陆大夫。\n煌煌新语在，拜手似皋谟。",""],["子真冠已挂，全性市门中。\n未肯营妻子，仙人让素风。",""],["梅公有贤女，堪配客星来。\n夫妇桐江曲，东西两钓台。",""],["至今七星濑，多有子陵鱼。\n翁婿皆高逸，垂光后汉书。",""],["孟光裘褐者，居与伯通邻。\n何似梅家女，风流在富春。",""],["陵园那可望，万里冷烟迷。\n辛苦子鹃鸟，年年向北啼。",""],["白虹犹饮恨，黄雀尚衔恩。\n亦有冬青树，何繇种御园。",""],["点点越罗衣，桃花作泪飞。\n鹧鸪如有意，为唤阿郎归。",""],["面脂调藁本，留半与薰裳。\n一任蛇床乱，薇芜自有香。",""],["木末芙蓉发，枝枝解向人。\n刺多伤女手，采摘不须频。",""],["横塘生水满，一半种蒲荷。\n更有茨菰草，根根乳子多。",""],["采摘日盈筐，香生比目房。\n食多能益智，本草有仙方。",""],["势急潮相叠，秋来水益骄。\n渔舟无旦暮，只是弄江潮。",""],["莫即叹飞蓬，醇醪更养蒙。\n秋花应似汝，老作雁来红。",""],["马上两蛾眉，鼙婆弄不迟。\n多因乳茶好，颜色似燕支。",""],["贳酒白云西，相将玉手携。\n无钱吾自分，门有泻钱溪。",""],["客心与春草，一路接江南。\n辛苦催归鸟，朝朝向片帆。",""],["荷花已成子，荷叶复成衣。\n一片蒲葵扇，团圆欲寄归。",""],["炎海少秋霜，叶红因客泪。\n因风片片飞，飞向江南坠。",""],["南枝能作花，岂若北枝好。\n霜雪平生心，岁寒聊自保。",""],["春来只烟雨，何必更留春。\n啼乌声声恨，情多太管人。",""],["桃花元有泪，不必雨啼红。\n滴滴苍苔上，吹干恨晓风。","桃花元有泪，不必雨啼红。\n滴滴苍苔上，吹乾恨晓风。"],["春山无远近，雨过总青青。\n云作蛾眉黛，愁人是翠屏。",""],["春色已牵肠，何须柳带长。\n海棠经泪洗，花白似秋霜。",""],["高卧不知处，花含古洞春。\n白云来借问，三诏彼何人。",""],["桃叶三春好，桃花复似霞。\n君心爱桃叶，不肯爱桃花。",""],["蝴蝶与芳草，相怜不为春。\n罗裙深浅色，愁杀冶游人。",""],["西苑接雷塘，花含粉黛香。\n流萤与明月，夜夜照君王。",""],["落月依荒戍，流烟暗里河。\n纷纷舵楼女，未曙唱吴歌。",""],["粤客龙须席，吴娘鸭嘴船。\n一声兰桨发，惊起月中眠。",""],["采花莫采叶，采叶恐伤藕。\n藕中多乱丝，缠绵那得久。",""],["莲白多生花，莲红多生子。\n采白莫采红，留红在叶底。",""],["种菱水宜浅，种藕水宜深。\n白白无人见，淤泥识此心。",""],["水肥多并蒂，色映白成红。\n叶大偏宜藕，田田满浦东。",""],["古木不成林，风含太古心。\n不须枝与叶，自可作悲吟。",""],["枝枝花上花，莲菊互相变。\n惟见西洋人，朝朝海头见。",""],["子熟无饥凤，枝枝坠露清。\n只须三两叶，便可作秋声。",""],["亦是珊瑚种，花开大似盘。\n石家如意好，击碎作山丹。",""],["珊瑚亦作林，红绝知三岁。\n自红开至黄，不忍离头髻。",""],["暮春淳菜长，半出湘湖水。\n水浅叶生多，不见茎茎紫。",""],["水深莼茎肥，叶少如钗股。\n性滑逐流波，吴娘休得取。",""],["愿君似山丹，红颜得长保。\n一开三月馀，黄落犹能好。",""],["一夕花荣落，终如木槿何。\n朱颜不可恃，流恨蕣英多。",""],["冉冉泰山竹，孤生只自怜。\n君非松与柏，那得女萝缠。",""],["郎采首阳甘，妾采首阳苦。\n甘苦不同心，枝条但相伍。",""],["苔青至秋紫，兰紫至秋红。\n妾自多颜色，承恩岁晏中。",""],["但教为菡萏，不愿作芙蓉。\n菡萏未开好，含葩似阿侬。",""],["藕花既相偶，莲叶亦相连。\n借问鸳鸯鸟，何茎最可怜。",""],["灼灼水芙蓉，中含青薏苦。\n花叶苦中生，莲心君莫取。",""],["泥水何愁浊，芙蓉且种来。\n藕中如有节，花叶自然开。",""],["与君情好蔤，白蒻在泥中。\n花叶生同节，相莲自始终。",""],["藕行元有路，深浅总耕泥。\n摘叶能伤本，田田开未齐。",""],["君心似明月，妾貌比菱华。\n与月相回转，青青映海霞。",""],["鲫鱼解相即，鲋鱼解相附。\n阿欢独何为，一去不回顾。",""],["侬如抱香枝，不离水松树。\n栽为木屧轻，随郎踏霜露。",""],["兔丝本无根，所恃惟茯苓。\n茯苓在松下，兔丝长青青。",""],["芭蕉亦有心，叶叶过墙阴。\n为尔含风雨，秋声一夜深。",""],["花叶长相偶，茎茎节上开。\n荷边休摘叶，留作一花来。",""],["不见园中树，花开只在枝。\n枝间结红豆，一子一相思。",""],["欢作槟门花，侬作扶留叶。\n欲得两成甘，花叶长相接。",""],["赠子槟榔花，杂以相思叶。\n二物合成甘，有如郎与妾。",""],["不及莲根好，泥中得偶生。\n鸳鸯花叶下，双宿到天明。",""],["不如池上藕，花叶得相连。\n花落莲房见，青青子可怜。",""],["菡萏含犹浅，青青带露寒。\n的中元有薏，莫但作莲看。",""],["怜花及桃叶，怜叶及桃根。\n古渡烟波上，相迎笑未言。",""],["怜桃及桃叶，爱柳及稊荑。\n但渡无言苦，兰桡我自持。",""],["忽破苔痕去，微微屐齿馀。\n落花真妒尔，片片在裙裾。",""],["蜂食花须落，黄沾几案多。\n海棠开未遍，已炙玉颜酡。",""],["未忍委苍苔，含情向玉杯。\n东风如有意，吹上故枝来。",""],["鸟声催雨至，向夕又春寒。\n花片不飞去，图君拾取看。",""],["石上一仙夫，箱中五岳图。\n不知张孺子，识得老人无。",""],["花朝花已尽，祗有绛桃肥。\n梅子青青好，流莺打不飞。",""],["人家尽木棉，花作一朱天。\n二月犹无叶，珊瑚十丈然。",""],["海棠晴暖候，红影满春山。\n朵朵如醇酒，酡人白玉颜。",""],["未开先吐蕊，蜂食为微黄。\n二月花寒甚，红成白海棠。",""],["香驻蛛丝细，微微吐紫烟。\n一春无事极，日把水沉煎。",""],["叶惹莺毛绿，花粘燕嘴红。\n生憎声𪾢睆，一一入愁中。","叶惹莺毛绿，花粘燕嘴红。\n生憎声睍睆，一一入愁中。"],["出上才双叶，抽心已一花。\n色应欺翠羽，香未减兰葩。",""],["与卿似芙蓉，花叶相偶生。\n摘花莫摘叶，花是叶所成。",""],["菡萏尚未发，芙蓉亦未开。\n距荷始出水，那得实莲来。",""],["藕荷在泥中，洁白祗自知。\n花生两叶后，节在不嫌迟。",""],["寄生松上萝，寄生桑上茑。\n为茑莫为萝，采桑人少小。",""],["茯苓龟鸟形，华山生者好。\n千岁附松根，赤白长相抱。",""],["氍㲣为裤口，白氎为陌头。\n行人见辟易，奴隶如公侯。",""],["得此壶浆女，千秋两浣纱。\n真州祠下树，香接苎萝花。","得此壶浆女，千秋两浣纱。\n真州祠下树，香接苧萝花。"],["东峰五十三，西峰四十八。\n同为百一峰，细细数奇拔。",""],["峰峰在谷中，芙蓉不可见。\n下注大龙湫，何峰多白练。",""],["南来雁荡馆，北去雁门家。\n不是峰峦好，何因别塞沙。",""],["一峰一回顾，知尔下山时。\n数遍东西谷，中峰不可知。",""],["贤后金罍酌，班姬亦羽觞。\n玉颜酡更好，试把索郎尝。",""],["每嫌明月夜，酒气太薰卿。\n不若同沾醉，氤氲直到明。",""],["儿寒捉熨斗，母冻方裁襦。\n箸襦儿已足，复㡓母所须。",""],["儿既上箸襦，复㡓不须作。\n箸襦下当煖，熨斗火方大。",""],["心甘和薏苦，一种在莲房。\n试把芙蓉擘，方知侬断肠。",""],["生憎双蛱蝶，终日镇相随。\n不是韩凭魄，何须风太吹。",""],["雨馀苔藓上，泥以燕衔香。\n一片馀春色，依依在画梁。",""],["小小比肩时，春来忍别离。\n不须烧鹊脑，已使妾相思。",""],["花豸尽情啼，郎行莫陇西。\n花含红泪落，片片湿香闺。",""],["身是珠儿女，穿钗不穿珠。\n将珠求媚蝶，一一系罗襦。",""],["香薰长在手，不必辟寒犀。\n心字烧难烬，和花作燕泥。",""],["愿作秭归鸟，催君春暮归。\n当归还有草，相寄莫相违。",""],["珍禽解姓秦，弄语向芳春。\n购得从蛮女，边鸾画不真。",""],["向花啼不已，一一是相思。\n更有山鹕好，雌雄总画眉。",""],["大小花含笑，风吹祗半开。\n幽香如夜合，一朵入窗来。",""],["芭蕉休剪叶，剪叶子生迟。\n滴滴宜疏雨，声寒秋夜时。",""],["距荷犹短短，叶小不胜珠。\n已有花相偶，参差出绿蒲。",""],["莲叶不多长，先花已作香。\n一珠愁荡漾，攀弄湿罗裳。",""],["叶小亦留雨，风吹珠不圆。\n泻时惊宝鸭，花下不成眠。",""],["大小过寒食，伤春泪未终。\n可怜花与鸟，都作杜鹃红。",""],["多谢青鵻鸟，槟榔要与郎。\n宁食我橄榄，莫食我槟榔。",""],["青鵻且莫来，槟榔犹未熟。\n莫食槟榔青，宁食槟榔肉。",""],["琼南无酒家，酒向椰中取。\n椰子有一心，出酒如娘乳。",""],["椰心在酒中，大似银桃子。\n浸以玉浆寒，食之甘且旨。",""],["双燕复双燕，生时不相见。\n相见在黄泉，雌雄何婉娈。",""],["持赠绿金蝉，为卿钗上饰。\n双栖朱槿中，相媚情何极。",""],["郎是簳珠儿，侬是薏珠子。\n自怜同一珠，甘苦长相似。",""],["携手南山阳，采花香满筐。\n妾爱留求子，郎爱桃金娘。",""],["蚕蛾多食叶，赢得腹中丝。\n辛苦得成匹，缠绵无尽时。",""],["蟾蜍月中兽，生与嫦娥居。\n多谢思君夕，流光满玉除。",""],["暮来妆阁冷，风使雪花多。\n若作春杨柳，当如飞絮何。",""],["不种忘忧花，但栽怀梦草。\n梦长在君傍，何惜忧终老。",""],["镜好终双照，妆成覆绿纱。\n墙阴休洒泪，恐作断肠花。",""],["冬深熟始黄，香甚为含霜。\n玉手休冰著，堆他在绣床。",""],["春来雪有香，片片惹衣裳。\n么凤殷勤甚，衔来欲点妆。",""],["江口夕阳低，孤帆影共西。\n要郎行不得，花豸好多啼。",""],["酒岂蠲愁物，须卿夜合花。\n端阳多采得，日夕泛流霞。",""],["六十一年前，吾诗已万篇。\n惟凭儿子记，未任老夫传。",""],["诗篇能暗诵，汝亦少陵儿。\n文选尤家学，精通及少时。",""],["谁将七宝月，击碎作玻瓈。\n绝胜菱花镜，来从洋以西。",""],["铸石那能似，玻瓈出自然。\n光含秋水影，尺寸亦空天。",""],["宁作黄鸳鸯，不作紫㶉鶒。\n鸳鸯解白头，双毛同雪色。","宁作黄鸳鸯，不作紫鸂鶒。\n鸳鸯解白头，双毛同雪色。"],["雄兔在月中，雌兔长相望。\n月中不顾侬，孕子何由两。",""],["百合蒜可怜，根根皆百合。\n赠郎百合根，花叶休相杂。",""],["卿生东越东，妾生南越南。\n参差数千里，来下凤凰簪。",""],["昔时刘碧玉，贪嫁汝南王。\n今时刘碧玉，但爱陇西郎。",""],["借问刘季姗，今亦行三否。\n定知姊妹中，辞藻人人有。",""],["千珠复万珠，难买绿珠子。\n不买绿珠生，但买绿珠死。",""],["为客寡欢娱，女爱移男爱。\n感君弃馀桃，多情不好外。",""],["女萝不自持，因依松树枝。\n松树长青青，照妾桃李姿。",""],["勿佩宜男草，迟迟生阿侯。\n年年十五六，天许莫愁不。",""],["四十未枯杨，生稊亦云好。\n虽非木槿花，亦自能爱老。",""],["东方娶小妻，一年即捐弃。\n君勿师容成，房中图秘戏。",""],["小妇不长妾，大妇不长妻。\n人生各有命，贵在与夫齐。",""],["??比翼好，栖我使君堂。\n使君留哺子，未许载还乡。",""],["太守主罗浮，神仙多女流。\n罗离与浮合，总惹使君愁。",""],["卿家日湖东，定家月湖西。\n送侬打两桨，先为到慈溪。",""],["慈姑白发多，垂腰乱如雪。\n为裁裙与襦，手爪不言拙。",""],["向日开偏早，清多亦畏寒。\n不知香欲满，尚作白云看。",""],["未出疏林外，幽香在薜萝。\n夜来全不见，却恨月明多。",""],["白头无一可，幸未愧梅花。\n冰雪同枯槁，无心任岁华。",""],["山鸟向人喜，梅开已满枝。\n衔将三两片，欲点美人眉。",""],["却嫌暄暖甚，未腊已开残。\n么凤莫收去，留香过岁寒。",""],["亦知花定落，不敢恨东风。\n苦是馀香在，魂消一片红。",""],["相将山喜鹊，花作一春粮。\n梅片兼残雪，清冷齿颊香。",""],["花发先春至，春风尚不知。\n年年同白首，多在苦寒时。",""],["故人惟汝在，不道是瑶华。\n香外无知己，氤氲自一家。",""],["孤荣亦已久，清绝自无人。\n幸在云山外，长含太古春。",""],["鱼食白云影，不知花满潭。\n持花作香饵，却被白鸥衔。",""],["赠欢百合根，根比?花好。\n大小总骈头，瓣瓣长相抱。",""],["赠欢多芬芳，华实一时好。\n宜母子在怀，宜男花在抱。",""],["上山日采樵，四十未成媪。\n因多脂粉花，颜色长能好。",""],["一春多泪痕，苔上无人扫。\n化作断肠花，复为断肠草。",""],["昔愁杜鹃多，今恨杜鹃少。\n杜鹃为我啼，莫惜到天晓。",""],["苦爱猿啼好，猿啼易断肠。\n断肠今已矣，化作望夫冈。",""],["蝴蝶花不香，鹧鸪草不长。\n长时为郎作，西去紫骝缰。",""],["蝴蝶亦有花，鸳鸯亦有草。\n花草总芬芳，要郎置怀抱。",""],["昔闻乌鹊好，不入宋王罗。\n又有香家女，同栖双燕窠。",""],["昔闻蝴蝶好，同宿青陵台。\n又有水西子，窠成双燕来。",""],["欲泛忘忧物，秋英采掇难。\n道旁多苦薏，亦作菊花看。",""],["小儿双角髻，状似折腰菱。\n欲与簪花朵，葳蕤恐不胜。",""],["不须冰与雪，自作一瑶华。\n人道水仙子，芙蕖是一家。",""],["数枝春粉嫩，箨解即琅玕。\n未忍青青玉，持将作钓竿。",""],["古渡从桃叶，沿洄到夕阳。\n青溪三十六，曲曲是愁肠。",""],["莺花三月艳，脂粉六朝香。\n不分青溪水，愁心与尔长。",""],["郎去不知还，风帆疾如马。\n愿似鸳鸯鸥，随潮时上下。",""],["今岁愁咸早，秋分害早黏。\n无多遗穗在，妇子亦腰镰。",""],["花时愁作飓，幸及肃霜成。\n留秆长三尺，烧盐作水晶。",""],["千钱租鸭步，争向女官沙。\n食罢三秋粒，禾生又海涯。",""],["沙田无晚稻，霜降已全收。\n衔穗多膏蟹，泥中拾满篝。",""],["几叶开筜谷，萧疏已作秋。\n笔端烟雨态，争向管姬求。",""],["望郎如枣子，今夜可来来。\n莫使流黄月，清光拂不开。",""],["生憎子巂鸟，不解一催归。\n啼杀枫林里，连弓弹不飞。",""],["烟水小长芦，微茫子大夫。\n不知垂钓罢，亦复著书无。",""],["瀑花无大小，吹落总成冰。\n一夜风含冻，草峰雪尽凝。",""],["敲泉惊宿鸟，乞火动邻僧。\n无与共吟啸，呼猿下古藤。",""],["柳花下阶砌，衣动香氤氲。\n蝴蝶不相识，亦来衣罗裙。",""],["花香不出林，谁识蕙兰心。\n幸得微风起，吹来满素襟。",""],["正色自难久，荣华祗一朝。\n自嫌因太赤，不欲斗娇娆。",""],["朱颜苦难驻，花里一蜉蝣。\n荣落须臾事，谁能得白头。",""],["白白复黄黄，雌雄知几行。\n春风吹不乱，各自宿花房。",""],["又植一株斜，虽阴不碍花。\n参差成五柳，人说似陶家。",""],["林下逍遥甚，猿裘与鹿巾。\n欲蠲霜露疾，多饮太和春。",""],["明月长悬君子光，风流文采自沅湘。\n与君共是三闾裔，骚赋相将作楚狂。",""],["日落江城鼓角悲，花田牧马暮归迟。\n蘼芜尚带罗裙色，满地秋霜知不知。",""],["古木飞泉万井中，茶人多戴杜鹃红。\n歌声真似莺声好，一路风吹听不穷。",""],["家家洗药有流泉，山上人耕尽茗田。\n妇女不知春色好，桃花一任落溪边。",""],["何来蝴蝶车轮大，知是罗浮小凤凰。\n更有仙禽皆五色，仙人为尔爱文章。",""],["痛饮狂歌度此生，从他竖子日成名。\n英雄只有安期子，玉舄翩翩东海行。",""],["罗浮四百玉芙蓉，上有飞桥跨两峰。\n君爱麻姑台上月，归来莫待海门钟。",""],["山山雪里肉芝肥，之子春深尚不归。\n长恨铁桥峰下水，东西分作两泉飞。",""],["为农只是种花田，花换春醪不用钱。\n更向梅花村里住，梅花持去酒如泉。",""],["袅袅飞猿下翠林，洞门花密昼长阴。\n松风吹尽人间事，不使兴亡上客心。",""],["梅花处处解相迎，洞口无人问姓名。\n几道飞泉天上落，乱随风雨作秋声。",""],["梅花村口水帘长，飞出春泉万壑香。\n红翠碧鸡知客至，相迎直至玉溪阳。",""],["行逐飞泉上白龙，人人分得一芙蓉。\n一声玉笛天边起，吹落梅花四百峰。",""],["百尺晴丝拂槛低，萦烟惹日柳条西。\n飞花片片劳相系，不使风吹作锦泥。",""],["二禺丹嶂削高天，四壁风雷响瀑泉。\n花满石床闲不扫，卧看秋月向人圆。","二禺丹嶂削高天，四壁风雷响瀑泉。\n花满石床閒不扫，卧看秋月向人圆。"],["袅袅松枝挂女萝，猿声故向月中多。\n征人一夕头如雪，三峡三泷奈尔何。",""],["舟子穿腰欲上天，下泷船笑上泷船。\n上泷争似下泷险，一片风帆乱石边。",""],["日日行舟穿乳窦，时时濯足弄萝川。\n青山两岸花相接，花里泉声应暮蝉。",""],["舟随瀑水天边落，白浪如山倒翠微。\n巨石有时亦却立，白鸥欲下复惊飞。",""],["百丈牵舟上瀑布，芙蓉乱落如烟雾。\n中流忽有石梁横，咫尺梅泷不可渡。",""],["上泷舟与雷霆斗，下泷帆共水帘飞。\n诸泷最是寒泷好，花底三秋雪湿衣。",""],["白头浪里山无数，两壁萝化飞满船。\n船与两崖为勍敌，下泷人助上泷牵。",""],["一泷烟雨一泷晴，泷口鸳鸯夹岸迎。\n风送猿声满城郭，行人忽起故园情。",""],["舟从潭底出天来，声似雷霆山欲摧。\n百道惊泉翠一石，波涛喷击几时开。",""],["峰峰白练挂天低，溱水萦回入武溪。\n日落渔舟不出峡，花中爱听鹧鸪啼。",""],["万叠奇峰接楚西，朝猿啼罢暮猿啼。\n三声已下征夫泪，玉笛何须奏武溪。",""],["一泷未过一泷来，细雨能添万壑雷。\n一日一泷行恐尽，篙人不用苦相催。",""],["江水随君万里流，年年天际一孤舟。\n浮云我亦无家客，朝向潇湘暮鹤楼。",""],["湘江东下连潇水，九绕衡山千里长。\n夹岸萧萧枫叶落，秋来谁忍过潇湘。",""],["潇水萦回落九疑，水清斑竹映枝枝。\n舟随七十二峰转，泪落湘江人不知。",""],["九疑山色照湘波，西接苍梧御气多。\n一自重华巡狩后，零陵风俗好韶歌。",""],["九峰九水落潇湘，古木寒烟夹岸长。\n欲就重华写哀怨，苍梧何处但斜阳。",""],["大江南北分云梦，七十名峰压水低。\n九向潇湘还九背，随波直至洞庭西。",""],["黄鹤晴川枕翠微，二楼高挟大江飞。\n天生瑜亮双年少，一片雄风在石矶。",""],["云际芙蓉十万枝，雨馀岩壑更生姿。\n一天飞瀑随风至，湿尽春衣人不知。",""],["庐山瀑布皆千尺，三叠飞泉势更长。\n三石梁边人不见，天风吹作满天霜。",""],["花茎虽比叶茎长，花气何如叶气香。\n寄语溪边采莲女，留将叶叶覆鸳鸯。",""],["峰峰花发白云香，雨过春泉迸石梁。\n七十二溪成一瀑，合流飞落玉渊长。",""],["乱石盘旋下白云，雨馀潭底数峰分。\n天边五老空招手，只见梅花不见君。",""],["朝来花露滴人香，睡起寒云满石床。\n欲剪水帘三十尺，挂君堂上共清凉。",""],["雨过溪云流有声，泉多处处水帘成。\n玉渊金井添千尺，一夕波涛万壑平。",""],["一片鄱阳九水通，茫茫吴楚有无中。\n云开忽见庐山影，半壁芙蓉挂白虹。",""],["华山谷口醉溪前，手把莲花饮玉泉。\n玉井流从天井出，酒星光向客星悬。",""],["玉井潜流作玉泉，中间二十八潭悬。\n水帘一道风吹断，乱落芙蓉更可怜。",""],["蒲池太上东西瀑，散作三峰雨雪来。\n玉女洗头馀碧水，至今长有白莲开。",""],["万里来攀太华峰，仙人咫尺见无从。\n情同玉井深千仞，望去莲花翠万重。",""],["飞骑相迎暮未来，愁看明月出云台。\n一声环佩天风落，双下雕鞍巧笑开。",""],["太华莲花并蒂春，红妆恼杀谪仙人。\n千秋愿作田田叶，双捧蛾眉出玉津。",""],["大小芙蓉总可怜，青莲今夕在谁边。\n东西南北皆莲叶，明月中当玉井悬。",""],["万仞莲花挂碧天，飞来苍翠玉楼前。\n美人双倚仙人掌，舞袖回风绝可怜。",""],["繇来太华双毛女，采药相携古丈夫。\n玉女窗开向秋月，与卿复结合欢襦。",""],["女生白鹿去翩翩，玉女相将下紫烟。\n自古仙人多好色，合丹不用独枝莲。",""],["洞口飞泉溅锦茵，丹青画出石仙人。\n半轮石月悬仙掌，绝似蛾眉出水新。",""],["玉泉如浆流落花，独坐姑姑餐月华。\n玉浆与侬作膏沐，明月与侬作丹砂。",""],["大者芙蓉小菡萏，已开何似未开花。\n双窥玉女潭中水，光乱青天一片霞。",""],["东峰西峰双石楼，与卿日日居上头。\n二十八潭作明镜，鸳鸯万古此嬉游。",""],["光彩阴阳过翠帏，陈王梦里是耶非。\n可怜白马无繇试，一代文章与宓妃。",""],["蒲城无数水芙蓉，天使萧郎独采侬。\n愿把兔丝来续命，千秋缭绕泰山松。",""],["首阳太华何时合，一道黄河苦间之。\n愁绝白云与秋色，风陵渡口望君时。",""],["慈峨水落满双溪，文杏花开二月齐。\n无限红颜随马足，雨来俱作锦障泥。",""],["终南万里带秦天，宫阙虚无苍霭边。\n白阁寻君还紫阁，似闻清啸出风泉。",""],["紫塞三关控雁门，往时兵马若云屯。\n长城万里今何用，白草黄沙满血痕。",""],["万障西来作太行，三关北锁控渔阳。\n刑馀不惜王公险，献与青丝白马郎。",""],["黄水河西草接天，苍茫不见有人烟。\n扬鞭日暮争飞鸟，望断孤城雨雪边。",""],["舞尽春风万万条，白花飞送马蹄遥。\n如何只见人离别，岁岁年年此灞桥。",""],["雁门八月无鸿雁，避雪罗浮去不违。\n我忆罗浮有慈母，梦魂先逐雁南飞。",""],["红颜三载老风沙，处处人怜白鼻䯄。\n金尽何须更游侠，早将清泪别琵琶。","红颜三载老风沙，处处人怜白鼻騧。\n金尽何须更游侠，早将清泪别琵琶。"],["难别金城太守贤，愁心如雪满秋天。\n英雄自古为厮养，不必投人宝剑篇。",""],["云州白草接天低，一片边声乱马嘶。\n泪共桑干流不尽，故人相忆白登西。","云州白草接天低，一片边声乱马嘶。\n泪共桑乾流不尽，故人相忆白登西。"],["边城太守独君贤，射猎相将雨雪边。\n天作三关雄紫塞，飞扬应在武安前。",""],["楼烦一片古风沙，吹乱愁心似雪花。\n宁武关前别君去，梦魂犹自怯秋笳。",""],["泪逐桑干出塞流，三年三度走云州。\n龙沙却喜无春草，不惹王孙日暮愁。","泪逐桑乾出塞流，三年三度走云州。\n龙沙却喜无春草，不惹王孙日暮愁。"],["紫河东合黑河流，河上风沙飒飒秋。\n千里黄云吹不散，望乡愁上代王楼。",""],["君本豫章贞女树，一朝摧折向秋风。\n大名空在遗民传，白首同归恨不同。",""],["琵琶争唱玉娥郎，艳曲传来自武皇。\n一代文章馀乐府，孤臣泪洒雁门霜。",""],["往岁慈娥清峪边，佳人双鬓杏花烟。\n莺歌细雨谁能那，马惜残霞亦不前。",""],["一别黄河间白云，秦筝慷慨梦中闻。\n春光不到昭阳殿，绝代红颜却与君。",""],["生长邯郸二十春，平原那贵卖浆人。\n黄金未必如肝胆，且共开樽醉锦茵。",""],["伯劳东去燕西飞，万里相逢泪欲挥。\n莫道王孙难自食，春来淮上鳜鱼肥。",""],["走马阴山竞射雕，嘶风代马为君骄。\n英雄不向沙场月，那得铙歌合短箫。",""],["豪杰繇来厮养多，不逢张耳奈愁何。\n云蒸龙变知无命，早向深山弄薜萝。",""],["燕赵无人吊望诸，君来意气定何如。\n酒酣若是悲歌者，应念渐离堂下居。",""],["汉家才子盛西京，高帝从来爱楚声。\n尔继房中诸乐府，清商一奏感神明。",""],["我昨题诗太华峰，仙人掌上抱芙蓉。\n玉浆一就明星饮，赋比青莲思更浓。",""],["歌舞休将换玉骢，神仙只畏酒樽空。\n雁门亦有芙蕖好，醉共鸳鸯入水中。",""],["豫让桥边落日昏，徘徊往迹泪双痕。\n君怜国士能终始，自有干将解报恩。",""],["三峰好结一花龛，濯足时临玉女潭。\n莫驾琴高鲤鱼去，车箱一穴出江南。",""],["大同宣府岭头分，风卷边沙似白云。\n千里金城为谁壮，可怜空驻羽林军。","大同宣府岭头分，风捲边沙似白云。\n千里金城为谁壮，可怜空驻羽林军。"],["绿琴弹出碧笳声，出塞何如入塞清。\n一曲送君千万里，秋来应共雁南征。",""],["■鬌妆成犯晓寒，轩车不坐坐雕鞍。\n儿家世世为飞将，少小花骢出贺兰。",""],["挥鞭北度雁门关，夫婿相将万里还。\n入塞更须先出塞，不辞风雪损朱颜。",""],["而亲远在固原州，西望乡关泪欲流。\n白发姑嫜因未见，艰难万里向罗浮。",""],["行人夜半饭黄羊，不待天明向战场。\n一路明驼载儿女，白登山下踏秋霜。",""],["金凤井边朝出店，白羊城下暮登台。\n路傍多少当垆女，笑问罗敷何处来。",""],["羊酥雪酒敌寒风，共吊明妃白草中。\n欲得卿卿发皓齿，胡雕一箭落秋空。",""],["西辞花马池边月，东指楼烦岭上云。\n往日于归悲道远，边风吹泪湿罗裙。",""],["怜卿万里别西秦，与我鸳鸯共一身。\n不道秦嘉异乡里，秦嘉元是陇西人。",""],["边姬一一口西曲，相送胪朐河水旁。\n箜篌弹尽不能别，泪湿征夫铁裲裆。",""],["青骹换得紫骝马，亦有琵琶与塞姑。\n到家沉水为槽逻，弹出秦声绝代无。",""],["红草东连白草沟，紫河西入黑河流。\n无边觱篥吹斜日，动尔思乡一片愁。",""],["黄羊野马满沙陀，朝渡杨河暮柳河。\n一路胡姬夹毂问，持来羊酪一何多。",""],["西指长城为乡道，我归路与长城长。\n青为明妃墓边草，白是阏氏营上霜。",""],["行尽桑干万里沙，北风吹雪损铅华。\n从伊妇女多颜色，不采燕支山上花。","行尽桑乾万里沙，北风吹雪损铅华。\n从伊妇女多颜色，不采燕支山上花。"],["九月云中雪不迟，香貂初上髻鬟时。\n酒酣共射阴山兔，双兔雌雄谁得知。",""],["夜夜毡车宿陇头，不登辽后洗妆楼。\n夫人自爱磨笄石，天际苍苍一片秋。",""],["欲向京师视宫阙，驱车千里入居庸。\n与君黻佩非今日，且复行歌返碧峰。",""],["高士繇来重妻子，莫将梅福比梁鸿。\n五噫歌罢今当去，去向姑苏台以东。",""],["一声鸡唱整衣裳，眉黛沾残子夜霜。\n行到白门春色满，梅花为尔点新妆。",""],["走马渔阳路尽时，天津东下逐流澌。\n北风一夜河冰合，又舍兰舟汶水湄。",""],["日出河冰流有声，舟人一路击冰行。\n三朝三暮清河口，幸有香醪慰尔情。",""],["渡河未已渡江淮，买舟用尽头上钗。\n日日牵舟上冰去，苦寒娇女在中怀。",""],["汝舅怜予华岳吟，因将窈窕慰文心。\n蹇修复有青莲客，司马无烦绿绮琴。","汝舅怜予华岳吟，因将窈窕慰文心。\n蹇脩复有青莲客，司马无烦绿绮琴。"],["使君羔雁为予将，千骑迎来自朔方。\n与子得成兄弟好，都繇幕府重文章。",""],["罗敷潭上昔相逢，鸾鹤相将太华峰。\n真似秦时丈夫者，玉姜携手上芙蓉。",""],["一从玉女洗头罢，二十八潭流水香。\n与尔秦时一毛女，双双玉井作鸳鸯。",""],["何以字卿曰华姜，明星玉女共翱翔。\n华夫相对三峰上，一片琴声瀑布长。",""],["采药从今向白云，与卿携手思氤氲。\n仙人不肯轻离别，方朔繇来爱细君。",""],["雁门高士称王霸，偕老山中有逸妻。\n今卿不复惭儿女，亦共雁门关以西。",""],["江南归去罢游猎，骏马名鹰赠与人。\n之子鸡鸣不用赋，锦衾高卧落花春。",""],["停骖太白酒楼傍，一树桃花娇晚妆。\n稚子只今在东鲁，女儿亦欲字平阳。",""],["元亮繇来爱弱女，慰情亦与五男同。\n为卿更取题诗笔，娇女新篇拟太冲。",""],["谢家生日逢人日，宜寿巧将华胜裁。\n归去炎州有翡翠，为卿多作宝钗来。",""],["笔花何似脸花妍，蝴蝶新辞亦可怜。\n珍重莫书桐叶上，奁中尚有浣花笺。",""],["去年寒食在平凉，汝妹催上秋千场。\n明岁花田踏青去，小姑三五牵衣裳。","去年寒食在平凉，汝妹催上鞦韆场。\n明岁花田踏青去，小姑三五牵衣裳。"],["大江明日片帆飞，南指梅花大庾归。\n新妇秦筝多逸响，朝朝暮暮奉庭闱。",""],["生儿慎莫生神仙，我学苏枕去几年。\n今得采兰娱膝下，不思骑鹤向天边。",""],["大姑既有胭脂巷，小姑亦有蛾眉洲。\n今夕兰桡与卿驻，彭郎不得擅风流。",""],["湖水合将江水流，与卿日日乘轻舟。\n相怜一片鸳鸯水，白浪如山亦不愁。",""],["江之水浊湖水清，我如江水湖如卿。\n可怜江水将湖水，清浊同流无限情。",""],["小姑山接大姑秋，不逐长江江水流。\n彭郎矶上一明月，飞去飞来共白头。",""],["生长秦川不见梅，红梅今夕为君开。\n家中绿萼香应满，折取先浮上寿杯。",""],["南枝花白北枝红，红是秦中白越中。\n辛苦鸳鸯飞万里，今宵始宿庾关东。",""],["渐近乡园尔莫悲，南飞应有北飞时。\n南中何物持相慰，尚有梅花及荔枝。",""],["依然虎踞复龙盘，一片钟山日夕看。\n天作双峰为凤阙，真人长在五云端。",""],["日日江皋望紫烟，天风吹泪孝陵边。\n六朝松柏知多少，苍翠人思乙酉前。",""],["云际屏风岭最尊，松杉一路夹天门。\n当时更有梅花树，十里天香接御园。",""],["石子冈前落日催，千秋人尚礼魂来。\n从来地下多生气，白骨何妨委绿苔。",""],["邗沟一水接长天，清浅偏宜暖板船。\n榆柳萧萧三十里，北风吹雪冻成烟。",""],["江南江北柳林中，三日舟行苦朔风。\n双桨如飞吹不转，秣陵东至海陵东。",""],["水落沙干川路遥，行行未尽十三桥。\n黄昏且驻仪陵市，露酒车螯慰寂寥。","水落沙乾川路遥，行行未尽十三桥。\n黄昏且驻仪陵市，露酒车螯慰寂寥。"],["日落平田海气凝，风飘万点艋船灯。\n两河水涨渔人喜，枫叶芦花处处罾。",""],["霜清水涸见渔矶，纲蟹何如簖蟹肥。\n三十盐场多海味，一帆相逐故人归。",""],["一江春水只流东，六代繁华似梦中。\n多谢垂杨与垂柳，依依犹向景阳宫。",""],["飞骑如云塞北回，六朝春色雪中开。\n行人莫折台城柳，曾沐先皇雨露来。",""],["三江春水五湖通，一片青天在镜中。\n日暮回舟向林屋，梅花无数与谁同。",""],["天涯一片愁中月，夜夜随风落故乡。\n何日寻君来欈李，二湖相并似鸳鸯。",""],["紫塞归来白发长，美人争拂镜中霜。\n鸳鸯湖畔开樽酒，一曲明妃尽断肠。",""],["万里罗浮今又归，天生越鸟自南飞。\n平生欈李多知己，争送扁舟向夕晖。",""],["枫泾水接泖湖长，白荡鲈鱼入馔香。\n为忆故人林屋洞，移舟西去及春阳。",""],["诸君亦渡太湖来，烟雨离亭更折梅。\n七十二峰空翠里，一峰花落一峰开。",""],["花多不见数峰青，如雪纷纷扑洞庭。\n一片离忧似烟雨，东风吹暗采香泾。",""],["他日寻仙去莫迟，金庭玉柱更相期。\n花边四皓诸孙子，共向烟波理钓丝。",""],["毛公坛畔一泉开，流入寒松万壑哀。\n拂石为君题姓字，风流长记七人来。",""],["梅花如雪扑青冥，香遍东西两洞庭。\n一棹吴淞君正返，相逢烟雨莫厘亭。","梅花如雪扑青冥，香遍东西两洞庭。\n一棹吴淞君正返，相逢烟雨莫釐亭。"],["洞庭七十二峰长，橘柚秋来香万家。\n我欲来栖范蠡宅，烦君石上扫萝花。",""],["花舫如云上虎丘，吴阊士女好嬉游。\n今宵醉杀横塘月，酒似金波天际流。",""],["处处楼台按十番，天边灯火若星繁。\n美人歌遍江南弄，谁听清商不断魂。",""],["今宵三五足欢娱，一片姑苏似玉壶。\n天作千人歌舞石，月华流满锦氍毹。",""],["一带船窗卷碧纱，人人歌管斗繁华。\n吴王往日风流在，狂杀苏台十里花。","一带船窗捲碧纱，人人歌管斗繁华。\n吴王往日风流在，狂杀苏台十里花。"],["真娘墓上玉箫声，十五当垆巧笑迎。\n一自君王能好色，至今吴女尽倾城。",""],["珠斗阑干兴倍豪，游人丝竹各分曹。\n金壶好注天河水，莫使东方日色高。",""],["锦帆泾水碧涟漪，往日夷光作水嬉。\n留得娟娟亡国月，美人千载学蛾眉。",""],["先朝蟒玉赐穿宫，亲见煤山血诏红。\n尝恨不同王内使，海棠枝上殉重瞳。",""],["不向西山陪玉匣，思来北塞引雕弓。\n何年始遂从军愿，无定河边作鬼雄。",""],["刀环何处贻都尉，马首当年逐冠军。\n无限关山行欲尽，晚来流落在三云。",""],["娘子营边杀气寒，朝朝围猎且为欢。\n酒酣射得南山鹿，妓女娇歌捧玉盘。",""],["苦忆英雄娘子军，女中勋业似桓文。\n南朝事去馀犀杖，泪洒炎天万里云。",""],["三朝绣幰自天来，百战金戈向日开。\n保障谁如女刺史，功名能冠越王台。",""],["郎心好似调黎水，不起风波春复秋。\n日日两潮还两汐，令侬消却别离愁。",""],["天脚遥遥起半虹，涛声倏吼锦囊东。\n天教铁飓吹郎转，愿得朝朝见破篷。",""],["花下欢闻白马嘶，郎来日日在南溪。\n莫如琼海潮相似，半月东流半月西。",""],["南亭溪畔二桥前，椰叶阴阴带暮烟。\n蛮女喜簪青茉莉，月明齐汲伏波泉。",""],["数钱争出手纤纤，叶结鸳鸯满玉奁。\n莫道槟榔甘液好，买侬椰子更心甜。",""],["蛮娘细葛胜罗襦，采葛朝朝向海隅。\n为有珠池名对乐，家家生女尽如珠。",""],["夕阳潮挟飓风来，欲渡琼南舟却回。\n望断所欢愁不见，青青一髻是擎雷。",""],["朔日城南小队过，鬟边祗要插花多。\n金钗竞叩三铜鼓，沉水齐薰二伏波。",""],["薄暮人人射猎归，城端秀塔挂斜晖。\n雷公庙里多箫鼓，十里风吹出翠微。",""],["一夕无衣寐不成，观山山上月凄清。\n松声卷起寒江水，散作风声与雨声。","一夕无衣寐不成，观山山上月凄清。\n松声捲起寒江水，散作风声与雨声。"],["明月娟娟似翠娥，登高临水奈君何。\n松声欲卷愁心尽，花片犹沾血泪多。","明月娟娟似翠娥，登高临水奈君何。\n松声欲捲愁心尽，花片犹沾血泪多。"],["山鸟朝朝唤客归，溪花日日染侬衣。\n鹧鸪亦解畏霜露，蝴蝶犹知暮不飞。",""],["楸玉相将日剧棋，兔毫赢得笔枝枝。\n还家赠与青娥妇，细作真书写楚辞。",""],["𫘦𬳿为食酪为浆，公主悲愁思故乡。\n黄鹄归飞不可得，岁时一会乌孙王。","騊駼为食酪为浆，公主悲愁思故乡。\n黄鹄归飞不可得，岁时一会乌孙王。"],["日落沙场铁骑飞，人人意气射生归。\n美人渴饮黄獐血，更请君王杀一围。",""],["五男未得如陶令，二女犹能似左思。\n羡尔惠芳兼织素，珠娘自可当珠儿。",""],["五年孔雀成金翠，三载夭桃已作花。\n少小谁能题柳絮，可怜娇女在君家。",""],["九岁解持甄后笔，十三能读谢公书。\n怀中玉映尤娇小，异日张玄妹不如。",""],["不必啾啾将九雏，只须皎皎吐双珠。\n明年老蚌君能似，孩笑还多膝下娱。",""],["一声风雨锦衾凉，不待秋深鬓有霜。\n泉下美人相忆否，三年秋夜为君长。",""],["之子相寻逐海潮，东樵朝别暮西樵。\n多情最是松间月，飞去飞来照寂寥。",""],["夹口横开燕子矶，崩崖千仞掠船飞。\n天风忽向芦花起，白浪如山打翠微。",""],["萧郎谢女久分飞，一在黄泉一翠微。\n青鸟不传天外信，可堪清泪日沾衣。",""],["琴鼓长歌复短歌，美人相逐出朝那。\n将军杀贼如围猎，毳帐前头醉叵罗。",""],["玉槛珠帘总一丘，春魂多半在迷楼。\n蘼芜亦爱雷塘路，十月青青自不秋。",""],["一路飞桥压水低，芙蓉多与酒船齐。\n依依最是三春柳，系得君王不复西。",""],["春云黯黯美人斜，秋草萋萋帝子家。\n一代红颜在何处，可怜都作广陵花。",""],["一片平芜接海天，江南山色堕楼前。\n双双浮玉天风外，空翠飞来化作烟。",""],["峨眉洞穴此潜通，千里陂陀与蜀同。\n泉水谁言君第五，先朝日月出其中。",""],["万壑松声吹泬寥，一松飞作一天桥。\n嗟君老作黄山客，独采松花不我招。",""],["一声风雨客初愁，不唱啼乌泪已流。\n今夕樽前须尽醉，黄花犹为故人秋。",""],["明月高高廿四桥，南弦北管坐相邀。\n谁能即策花骢去，不向扬州度此宵。",""],["万里天河淡欲分，玉杯飞处湿行云。\n多情最是齐梁曲，恨尔江南夜夜闻。",""],["神仙富贵未蹉跎，自古英雄白首多。\n请语梅花楼外月，清光长照玉人歌。",""],["战鼓无声落日黄，英雄自古是天亡。\n乌骓不失阴陵道，岂有山东与汉王。",""],["战血淋漓洒美人，君王意气委黄尘。\n多情不渡乌江水，为有红颜在草茵。",""],["缥缈青山接燕矶，风吹浮玉渡江飞。\n谁家故起真州阁，收尽江南彩翠归。",""],["潮去潮来怒未平，蕲王庙口客心惊。\n天风不断黄天荡，知是当年战鼓声。",""],["新长沙洲廿里长，蒹葭斜抱石城墙。\n江南岁岁添形势，料得天心在建康。",""],["十万垂杨作一城，双堤流水绕香粳。\n中田百顷桃花里，安得斯人共耦耕。",""],["签蟹新肥煮酒香，旅人初在泰州尝。\n知君家有茅容母，更买鲈鱼奉一觞。",""],["一路车篷夹岸多，一重官柳一重河。\n天寒不惜牵舟苦，为有君园在薜萝。",""],["天生意气逐重瞳，血作名花万古红。\n开遍青溪与罂粟，枝枝平舞美人风。",""],["一带溪桥隐暮烟，开残芍药马蹄边。\n红颜尽是闲花草，似尔虞兮自可怜。","一带溪桥隐暮烟，开残芍药马蹄边。\n红颜尽是閒花草，似尔虞兮自可怜。"],["战血何妨染玉颜，花开长使美人攀。\n二妃不为重华死，那得潇湘竹尽斑。",""],["却嫌月照海棠白，花下频将蜡炬催。\n竹叶未倾颜已赭，明霞朵朵火中开。",""],["长忆明星玉女宫，洗头盆映暮霞红。\n飞泉乱出莲花腹，散作诸溪处处通。",""],["乱瀑淙淙响石床，梦馀无奈落花香。\n含毫欲写泉三叠，心与云英化水光。",""],["闲与天台扫落花，花花扫尽扫云霞。\n云霞亦是吾馀物，流出人间带日华。","閒与天台扫落花，花花扫尽扫云霞。\n云霞亦是吾馀物，流出人间带日华。"],["天半飞桥势欲飞，赤城霞作羽人衣。\n天风不断松间起，乱洒流泉湿翠微。",""],["明月飞来珠海长，愁心尽与白云乡。\n高歌试问投竿老，我是今狂定古狂。",""],["谁能学道更情深，兴俗今朝共陆沉。\n金粟如来吾不屑，但将尊酒送狂吟。",""],["幽州二月柳堪把，小姬邀客玉河下。\n莫道酡酥不醉人，频向津楼系白马。",""],["淮南自善离骚赋，不必诸儒大小山。\n已作三闾高弟子，绝胜黄屋入秦关。",""],["云舟轻漾采菱蕖，太液池中春雨馀。\n飞燕随风欲入水，君王频为结缨裙。",""],["暮烟朝雨荚陵开，环佩珊珊去不回。\n终古哀蝉将落叶，君王泪洒集仙台。",""],["新声乐府推君妙，白燕丁香赋并传。\n燕女争歌玉河柳，扬州更爱竹枝篇。",""],["御沟春水玉河通，夹岸花飞随玉骢。\n欲赠君归须芍药，佳人争买点桩红。",""],["归泛西湖水渺茫，家临湖墅足蚕桑。\n梅花若向西溪问，曲曲渔舟共陆郎。",""],["尔祖丹青似辋川，草书团扇世争传。\n今君妙写沧洲趣，待诏风流在目前。",""],["乱后阊门无旧业，玉兰台馆委烽烟。\n移家远向天池住，文肃松楸怆墓田。",""],["东望莫厘西缥缈，天池楼阁太湖边。\n经营响屧琴台月，挥洒金庭玉柱烟。","东望莫釐西缥缈，天池楼阁太湖边。\n经营响屧琴台月，挥洒金庭玉柱烟。"],["商山四皓多苗裔，遍植梅花林屋间。\n我昔采香西子径，洞庭春尽不知还。",""],["梦中林屋树苍苍，掩映人家橘柚黄。\n更有杨梅无数树，蒲萄处处绿阴凉。",""],["凭君点染包山翠，多写毛公洞口松。\n挂向长安散炎暑，一杯一朵玉芙蓉。",""],["今夕觞同河汉倾，满堂凫藻目先成。\n但教南海明珠在，不必青天皎月生。",""],["邯郸公子善娱宾，玉貌樽前映塞春。\n欲得荆轲捐七尺，祗须宝马与佳人。",""],["身轻忽到巨灵旁，长揖明星乞玉浆。\n十丈莲茎持作杖，因探玉并不嫌长。",""],["洗头盆里水初寒，明月偏宜镜里看。\n二十八潭闲照遍，玉颜新似水花丹。","洗头盆里水初寒，明月偏宜镜里看。\n二十八潭閒照遍，玉颜新似水花丹。"],["玉女祠前有醴泉，张超谷在玉泉边。\n二泉酿就三峰去，醉向仙人掌上眠。",""],["渭川东泻黄河月，雷首西横太华云。\n咫尺蒲关愁不度，明星玉女惜离群。",""],["袅袅天边铁绠垂，攀援无那峡风吹。\n愁君日向苍龙岭，鸾鹤翩翩不可追。",""],["青州玉露胜金露，君去青州作酒人。\n一醉莫教三十日，醉乡春好本非春。",""],["今夕双星乐事多，愁人不寐盻银河。\n云中有路通明月，谁许乘槎泛浩波。",""],["滹沱秋水耶溪似，莲叶东西见彼姝。\n万里长风吹海月，可怜光堕锦氍毹。",""],["巫山句注两氤氲，十二芙蓉望不分。\n最喜黄牛朝暮见，俨如神女在行云。",""],["天边明月不曾愁，万里青光上塞楼。\n我似微云在河汉，依依长抱玉盘游。",""],["一曲归风响入云，留仙争把汉宫裙。\n思为海燕巢君屋，处处衔将兰蕙芬。",""],["潺湲一道落桑干，中有征人泪未寒。\n愁绝三云驱马去，年年花向战场看。","潺湲一道落桑乾，中有征人泪未寒。\n愁绝三云驱马去，年年花向战场看。"],["九月辽东衰草多，飞霜乱下白狼河。\n人人马上吹芦管，夜夜城头枕铁戈。",""],["薄暮桑干大猎还，纷纷雨雪暗关山。\n天寒不惜貂裘典，一醉春光上玉颜。","薄暮桑乾大猎还，纷纷雨雪暗关山。\n天寒不惜貂裘典，一醉春光上玉颜。"],["万里挥鞭辞玉颜，愁心不断似天山。\n天生飞将从无命，笑向沙场射虎还。",""],["卿本佳人自不知，相逢蔓草露零时。\n殷勤问我离骚赋，欲共潇湘采竹枝。",""],["怅望湖天祗去鸿，洞庭花映白云空。\n银鱼一尺春来美，欲寄相思秀水东。",""],["白雨频催荔子红，蝉声凉带芰荷风。\n林塘好是清和候，无奈君行向海东。",""],["残梦微茫逐水流，送君帆席影沉浮。\n他时倘忆罗阳月，应有音书到石楼。",""],["瀑布高悬三石梁，湖波荡漾白云光。\n仙人双足垂明月，绝世风流不可忘。",""],["江汉南流有合时，情人咫尺苦生离。\n散花洲上空相忆，却月城边自不知。",""],["故园又复返沙亭，绕屋峰峦作画屏。\n兄弟行中吾与子，遗书真解读骚经。",""],["素馆依然水木间，四围多是未名山。\n最高峰好惟烟管，与子长乘采药闲。","素馆依然水木间，四围多是未名山。\n最高峰好惟烟管，与子长乘采药閒。"],["无多白发不教催，一月童颜驻一回。\n吾道自令颜色好，金精石髓本尘埃。",""],["何曾一日得为人，五十三年未见春。\n人日休为人日酒，年年人日总伤神。",""],["闺人生日是今朝，花落兰房久寂寥。\n十二年来罢人日，泪珠为酒滴妖娆。",""],["江山虽好恨无人，不用莺声换好春。\n人日与谁还燕饮，英雄一一作青燐。",""],["牛渚孤从天际浮，天门双夹大江流。\n开平古庙多松柏，归对风烟一片秋。",""],["虎踞江间惟采石，江南门户此为雄。\n千秋战鼓声犹在，愁尔真人想像中。",""],["地当南极老人多，况复沙亭满太和。\n兄在吾宗今最长，千钟将奈寿星何。",""],["兄采芝华弟采薇，薇香不似紫芝肥。\n衣冠甚伟他年得，与尔同扶鸿鹄飞。",""],["君年一百还馀九，是我如君八十时。\n倘得杖朝兼杖国，求兄海上与安期。",""],["今宵只有岁星明，织女银河渡未成。\n欲为吾兄酌天酒，碧梧枝上露华清。",""],["千里桑干入塞来，参差城阙镜中开。\n君王往日多凫雁，肯念思波太液回。","千里桑乾入塞来，参差城阙镜中开。\n君王往日多凫雁，肯念思波太液回。"],["二月流澌上玉河，酒楼一一俯晴波。\n春衣笑向垆头解，醉拥琵琶卧紫驼。",""],["撑折千篙不上滩，留郎一日不胜难。\n郎情不似鸬鹚石，日日双浮水上寒。",""],["采药凌峰不觉遥，耶溪频负道猷招。\n谈经近厌天花满，欲谢时人隐沃焦。",""],["从今泪应竹枝歌，秋夜猿声三峡多。\n况复峨嵋一片月，飞来飞去奈君何。",""],["将军教射五千人，荆楚奇材总绝伦。\n秋出阑干当一队，骁腾不逐贰师尘。",""],["千骑横穿卤阵还，髦头一夜落天山。\n军中女子皆诛尽，士气飞扬战鼓间。",""],["精兵扼虎五千多，后距何烦路伏波。\n龙勒秋来觇敌去，黄门骑吹杂铙歌。",""],["阴山风雪暮纷纷，独出旌门望卤群。\n天子深恩怜浞野，重将血汗洒边云。",""],["香貂宝马猎天山，塞女酡酥捧未闲。\n长与丁零俱用事，汉臣无计赠刀环。","香貂宝马猎天山，塞女酡酥捧未閒。\n长与丁零俱用事，汉臣无计赠刀环。"],["太华峰边有醉溪，醴泉更在玉泉西。\n酿泉作得松花酒，山女教人醉似泥。",""],["醉度苍龙岭似飞，羽人争揽紫霞衣。\n生憎瀑布三千丈，遮却天边白玉妃。",""],["虎斗笼争寂不闻，銮舆频别靖南军。\n长安旧帝无人识，空有阏氏拜彩云。",""],["沙冷秋高战马闲，蕃儿千队锦衣还。\n江南天子单于客，竞献酡酥毳帐间。","沙冷秋高战马閒，蕃儿千队锦衣还。\n江南天子单于客，竞献酡酥毳帐间。"],["烟云霏霏碧草齐，断肠春在孝陵西。\n松楸折尽寒山露，无处堪容杜宇啼。",""],["高台一上一含悲，况复清明上巳时。\n多谢朝烟兼暮雨，不令人见蒋山姿。",""],["二陵寒食雨连天，禾黍荒凉复几年。\n愁绝江南空骋望，君臣犹隔九疑烟。",""],["春去风花飞更狂，马蹄无主踏残香。\n丝丝最恨河边柳，日夕牵愁短复长。",""],["朱雀门前花草空，明驼尽载景阳宫。\n六朝春色龙沙去，一片江南雁塞同。",""],["浮玉山中浮玉春，醉来忘却华阳巾。\n天风吹上雷轰石，一夜啸声惊羽人。",""],["四皓旧楼林屋洞，今君清啸莫厘峰。\n楼前七十二峰月，不及仙人冰雪容。","四皓旧楼林屋洞，今君清啸莫釐峰。\n楼前七十二峰月，不及仙人冰雪容。"],["沙河双绕巩华城，一道飞桥接帝京。\n往日君王上陵寝，红旗翠辇此中行。",""],["高柳城边折柳多，送君千里渡榆河。\n美人骏马平生物，欲赠其如白发何。",""],["黔中多雨少人行，尽道天无三日晴。\n千里茫茫烟务海，雨师偏好贵阳城。",""],["千叠峰峦万叠岚，奔腾不断至安南。\n雨从山下朝朝起，山上晴多见玉簪。",""],["攀花日日出江潭，泪落他乡酒半酣。\n杜宇多啼偏向北，鹧鸪有志但怀南。",""],["荆门西上即瞿塘，一路猿声莫断肠。\n应有巫云化神女，朝朝暮暮慰思乡。",""],["蜀道无如三峡难，猿声况复满诸滩。\n滩多峡少滩尤险，日日篙舟不及餐。",""],["生竹青青作缆长，鼓声须急缆须强。\n将舟一折穿危石，滩滪堆边险莫当。",""],["临风一啸作秋声，天籁何如人籁清。\n南郭先生休隐几，须知鸾鹤不胜情。",""],["谁驻兰桡海上洲，不将明月照人愁。\n一声风雨笙歌乱，始信仙人不下楼。",""],["旗门直入报仇还，孝子威神岂等闲。\n天马不惊樗里去，坐令追吏至深山。","旗门直入报仇还，孝子威神岂等閒。\n天马不惊樗里去，坐令追吏至深山。"],["雄刀三载箾中鸣，报怨而今事已成。\n何必君思频见赦，千秋人识子崔名。",""],["舍人词赋擅西京，春日开筵五凤城。\n我有麻姑台上月，光华不减许飞琼。",""],["月华特献太夫人，王母桃花莫与伦。\n散作朝霞与令子，文章丽似上林春。",""],["知子云天义至高，相逢每念笔耕劳。\n养亲未有雕胡饭，惭愧山阴一顾翱。","知子云天义至高，相逢每念笔耕劳。\n养亲未有彫胡饭，惭愧山阴一顾翱。"],["江山战后日萧条，壮士闻笳惨不骄。\n兄弟登高犹九日，君臣失路已三朝。",""],["门外双湖水合流，丰湖春似鳄湖秋。\n有时象岭烟霞散，隐隐空中二石楼。",""],["湖心亭子更风凉，山雨飞来若散霜。\n莲叶莲花争出水，不愁无处宿鸳鸯。",""],["九月银鱼出水长，银鱼风起水泱泱。\n银瓶汲取姚坑水，来煮银鱼香复香。",""],["可惜江山今已非，先臣功业在金微。\n汉家祗有天山月，来照樽前旧锦衣。",""],["不嫁吴王凤作群，山中偃卧发纷纷。\n冰纨照面如明月，石鼓歌声入紫云。",""],["新梳堕马可怜妆，独少秦珠耳后光。\n此去青莺池上买，归来明月照兰房。",""],["雷阳纫葛杂银条，一著凉风生舞腰。\n应倩纤纤蛮女手，为卿织得比龙绡。",""],["日斜花始渡江来，一到云鬟花尽开。\n博奕输卿花百串，将花结作素馨台。",""],["学写曹娥未就时，闲来只爱弄花枝。\n何当结得樱桃子，不负春风作意吹。","学写曹娥未就时，閒来只爱弄花枝。\n何当结得樱桃子，不负春风作意吹。"],["牡丹新髻出维扬，衣带题春句有香。\n纤手把将团扇好，练巾携拭口脂长。",""],["凌晨画就鸳鸯眉，纤手频来擘荔支。\n输与郎君三百颗，花前不肯再弹棋。",""],["越女年来多善书，钟王笔法学无馀。\n珠江郑卉年犹小，势得惊鸾总不如。",""],["兼临画本作丹青，花鸟如生出素屏。\n前掩林良后张穆，天南绘事一娉婷。",""],["垂髫已作女棋师，玉子纵横落不迟。\n岑李近来称国手，岂知无敌在蛾眉。",""],["吾家闺阁有书生，夫婿为师学渐成。\n嗟尔聪明殊未遇，不知谁可教飞琼。",""],["十月嘉鱼出穴来，随波东下至崧台。\n梧州寄酒冬尤美，莫惜天寒匹马回。",""],["家在沙场不忍回，他乡秋色老相催。\n忧心一片长如醉，不必貂衣换酒来。",""],["湘漓二水陇头分，一道飞流出白云。\n漓水不如湘水好，君行更为吊湘君。",""],["妆楼寂寞委苍苔，春到梨花不忍开。\n一片愁心乱如雪，东风吹去复吹来。",""],["垂垂腰下绣囊长，中有槟门花最香。\n一笑行人齐下骑，殷勤紫蟹与琼浆。",""],["鸳鸯相对已忘机，共命何曾要共飞。\n天女有花空自散，风吹不著净名衣。",""],["闻君荔子满棠溪，五月胭脂裹玉齐。\n欲向佳人分万颗，香随翠笼过桥西。",""],["枝枝露滴紫金盘，千叶葳蕤胜合欢。\n花萼同心兄弟似，殷勤簪向御风冠。",""],["绿叶丹葩连理枝，折来偏与玉冠宜。\n迷花自是仙人事，周蝶逍遥两不知。",""],["木兰枝上露瀼瀼，津液因之吸正阳。\n之子采花数相赠，为怜屈子爱芬芳。",""],["屈子餐英自润泽，正阴精蕊在秋花。\n不如朱夏木兰好，与尔凌朝饮露华。",""],["雨过苍苍海目开，早潮未落晚潮催。\n鲥鱼不少樱桃颊，与客朝朝作鲙来。",""],["烂鳞粉颊满渔船，煮用涓涓海目泉。\n海目山人不可见，中流一啸?寄川。",""],["羚羊峡口嘉鱼美，不若鲥鱼海目鲜。\n黄颊切来纷似雪，绿尊倾去更如泉。",""],["刮镬鸣时春雪消，鲥鱼争上九江潮。\n自携鲙具过渔父，双桨如飞不用招。",""],["后皇嘉树产番禺，朱实离离间叶浓。\n珠玉为心君不见，但将颜色比芙蓉。",""],["蓬莱一岛海浮来，上有离支下有梅。\n五色仙禽餐不尽，纷纷衔过越王台。",""],["绿萎青华似桂丛，岁寒攀折与谁同。\n南州炎德钟花木，郁郁冬荣雨雪中。",""],["六月增城百品佳，居人只贩尚书怀。\n玉栏金井殊无价，换尽蛮娘翡翠钗。",""],["端阳是处子离离，火齐如山入市时。\n一树增城名挂绿，冰融雪沃少人知。",""],["照人最是凝冰子，五月光生一片寒。\n未启朱苞光已出，可怜更在水精盘。",""],["翡翠墟边种更佳，客来仙核不须怀。\n葡萄此日应归汉，橘柚繇来不逾淮。","翡翠墟边种更佳，客来仙核不须怀。\n葡萄此日应归汉，橘柚繇来不踰淮。"],["东洲烟水接西洲，载出离支万斛舟。\n自夏徂秋皆辟谷，不知人世有通侯。",""],["扶胥江口祝融宫，积水茫茫吐日红。\n十里缃枝连黛叶，朝来一望海霞同。",""],["未曾夏至难齐熟，最喜蝉声日日催。\n笑口但令香玉满，愁心尽与绛囊开。",""],["风里氤氲杂芰荷，闻香不觉玉颜酡。\n兰膏倘得长滋润，白发如丝奈我何。",""],["小至清甜尽上糖，宋香陈紫最先尝。\n夜来坐对青天月，心似云英化水光。",""],["龙眼独从阴处长，荔枝先向日边红。\n仙人肌体如冰雪，玉液丹成大火中。",""],["雨月山中烟火寒，春衣典尽为琅玕。\n仙人服食如无汝，那得红颜生羽翰。",""],["何来香似素馨花，生长花田越女家。\n汉使当年推第一，兼携抹丽向京华。",""],["愁来急泻青丝笼，欢至频开翠羽帘。\n中酒更须含绛雪，如花不用进红盐。",""],["日夕林中坐紫苔，一杯一颗荔枝开。\n天将汝作仙人禄，好断人间烟火来。",""],["朱楼初日上窗纱，镜里妆成阴丽华。\n不用胭脂边地草，但调南国露头花。",""],["罗衣乍解汗如珠，烛下光生白玉肤。\n更爱昭仪膏滑甚，兰房出浴不曾濡。",""],["罗浮蝴蝶大如云，旧是麻姑五色裙。\n火齐竞餐仙树上，化为威凤影缤纷。",""],["满山红翠教飞时，荔子低低拂水湄。\n红翠爱雏毛羽好，为巢不敢在高枝。",""],["蝙蝠千年白雪同，一餐扶荔羽全红。\n双飞双宿芭蕉树，服可成仙似葛洪。",""],["雾縠轻衣著未曾，明珠新出玉壶冰。\n君看不是鲛人泪，日月精华一片凝。",""],["系马高楼日欲斜，笑攀琼树美人家。\n冰盘共载同心藕，翠袖兼携并蒂花。",""],["水上园亭向晓开，主人尝后鸟群来。\n多情不忍和枝折，留取芳阴在绿苔。",""],["甘酸二味总宜人，髓滑兰香妙入神。\n烈日正中看尽熟，红如血珀媚卿唇。",""],["绛雪含滋不留齿，十分膏润可生津。\n朝来被酒清狂甚，一颗能成独醒人。",""],["神农本草未曾知，绝代容华过岭迟。\n一自汉宫抉荔筑，尽惊南海有琼枝。",""],["辞汉金人去不回，帝思甘露万年杯。\n炎方幸有三珠树，剖出天桨进御来。",""],["枝枝交荫钓鱼矶，翠鸟啾嘈食尽肥。\n雨桨溪边随意摘，露华偏湿美人衣。",""],["七月株株是火山，抛书往摘不曾闲。\n小华山子尤多汁，红绣鞋儿亦自弯。","七月株株是火山，抛书往摘不曾閒。\n小华山子尤多汁，红绣鞋儿亦自弯。"],["一本分来花岭头，年年留得殿清秋。\n天鸡未唤扶桑日，已有霞光照海楼。",""],["蒲桃宫锦九天来，皇帝恩晖满越台。\n归汉自缘南海尉，至今春色上林开。",""],["正月花开香更清，酿为仙酒得长生。\n世人只解求丹实，真子先教采素英。",""],["绝似含消御宿梨，冰鲜玉脆更多肌。\n丹心一点成焦核，抛掷泥中君不知。",""],["渔父酒船香复香，春酥卖罢更琼浆。\n我持兰棹过前浦，醉向榕阴纳晚凉。",""],["美人天上忆琅玕，生长南荒绝羽翰。\n路入白云迷子午，心随红日到长安。",""],["甘溪水接菖蒲涧，南汉君王旧泛杯。\n岁岁红云张御宴，美人歌秦火珠来。",""],["一株高出少微家，膏叶当年覆翠华。\n一自端皇亲摘后，至今香烈胜群葩。",""],["初开芳汗湿微微，白白红红不染衣。\n委质玉盘思见食，葡萄石蜜似君稀。",""],["槛外已多鲜荔子，瓶中复有佛桑花。\n仙人好色无过此，两两朱颜伴鬓华。",""],["一队红妆娘子军，英雄多在石榴裙。\n花田百里为汤沐，香国千年驻彩云。",""],["五色穿将续命丝，珠娘笑掷与珠儿。\n兰桡相并沉香浦，好是龙舟竞渡时。",""],["锦苞初擘露华红，掌上寒光映月空。\n玉女之浆不忍咽，当年太华事相同。",""],["江南黑叶已称珍，玄墓杨梅敢与伦。\n塞外葡萄宜酿酒，燕中频果莫沾唇。",""],["五年不见水晶丸，今日酸时已饱餐。\n四月先红犀角子，故人分惠一冰盘。",""],["枝枝双结绛云阴，近蒂檀痕一点深。\n玉芝爱尔柔无骨，莲子怜他苦有心。",""],["露井寒泉百尺深，摘来经宿井中沉。\n日精化作月华冷，多食令人补太阴。",""],["三月桃花五月油，面脂香泽为谁求。\n荔支亦可娇颜色，无那佳人去凤楼。",""],["鸡鸣若木海先红，一片离支夜火同。\n露湿紫房晞不得，摘来天酒满杯中。",""],["木兰不用充朝饮，零露瀼瀼满荔支。\n可惜骚人曾不见，流甘委素美如饴。",""],["日领花篮摘数千，高堂真是荔支仙。\n儿孙一一皆丫髻，绿核喧争满膝前。",""],["侍女笑斟玄碧酒，高堂注以荔支浆。\n令予醉后一嘘噏，水露化作酥醪香。",""],["谁爱三闾橘颂辞，更将骚思写离支。\n曾含甘液方能赋，汉代风流有叔师。",""],["莲丝长与柳丝长，歧路缠绵恨未央。\n柳丝与郎系玉臂，莲丝与侬续断肠。",""],["紫梗西从海外来，染衣红似石榴开。\n芳香更有扶留汁，不必胭脂上口来。",""],["买鱼争唤向烟波，摇橹无如弱腕何。\n人好遂令鱼亦好，钱多不觉笑逾多。",""],["两日羚羊峡上居，鲥鱼下酒不曾虚。\n小姑鱼贵人偏买，用尽金钱为买鱼。",""],["咫尺梅关雪不来，梅花开罢腊梅开。\n炎州十月春如海，处处飞香半是梅。",""],["梅花十月已开齐，日夕花间素手携。\n玉映无惭顾家妇，冰清真是楚狂妻。",""],["合浦秋清水不波，月中珠蚌晒珠多。\n光含白露生琼海，色似明霞接绛河。",""],["中秋月满珠同满，吐纳清光一一开。\n明月本为珠作命，明珠元以月为胎。",""],["珠池千里水茫茫，蚌蛤秋来食月光。\n取水月中珠有孕，精华一片与天长。",""],["家家养得采珠儿，兼采珊瑚石上枝。\n珠母多生珠子树，海中攀折少人知。",""],["暮春争赛白龙池，挂席乘潮采不迟。\n千尺螺筐垂海底，翻波不使大鱼知。",""],["珠市西头近接城，客餐珠肉当琼英。\n廉州个个珠娘媚，祗为珠池水色清。",""],["东湖水接珊瑚洲，吏部开为万里流。\n高阳虽有酒池好，那得人人尽拍浮。",""],["虎门潮水与湖通，士女如山出镜中。\n香气皆为荷叶气，颜红尽似荔支红。",""],["天生一片素馨田，来作炎洲士女妍。\n多食荔支颜更好，楼船不隔碧纱烟。",""],["处处龙舟金鼓来，兰桡桂楫沸如雷。\n东江水斗西江水，夺尽花红暮未回。",""],["堤畔青楼隐柳阴，笑声时与水云深。\n东家蝴蝶西家燕，飞入芙蓉不可寻。",""],["船船尽挂宝镫来，万朵芙蓉火里开。\n明月满天照不入，光中人影乱楼台。",""],["善才三两弄蛮弦，水马如飞欲上天。\n羡杀金花倭帽客，夺标能得一婵娟。",""],["可怜一片镜湖水，祗有西施一浣纱。\n千载芙蓉为谁发，君归好上钓鱼槎。",""],["雪窦山人去几秋，弹琴东市亦风流。\n相思最是耶溪月，夜夜清光为我愁。",""],["谈禅昔爱祁居士，咳唾天花落石床。\n自向花边见天女，至今不散梦魂香。",""],["云门一老未龙钟，七十能登秦望峰。\n一代遗民在禅寂，袈裟空挂六陵松。",""],["处处沙场吊鬼雄，故人多在国殇中。\n钱郎侠骨香犹在，谁葬要离古墓东。",""],["怅望稽山宿草齐，故人墓在禹陵西。\n天生志士填沟壑，魂魄休为杜宇啼。",""],["梅市西边秋山波，中丞怀石恨如何。\n公孙爱我三闾裔，岁晏相邀卧薜萝。",""],["书台此日委寒烟，鸾鹤飘零各一天。\n君去落花应自扫，时时石上作春眠。",""],["汝亦多才似叔师，南方朱实写离离。\n明年若在萧山县，莫把杨梅拟荔支。",""],["薄暮人人待月华，三城争买素馨花。\n珠儿更比珠娘好，莫向耶溪苦忆家。",""],["珠江江上尽花田，花似明珠彩缕穿。\n粤女将花围宝髻，风流不到陆郎前。",""],["汝度梅关越两秋，乘桴几尽海南头。\n夜深欲见扶桑日，应上罗浮大石楼。",""],["英雄泪尽此刀环，我欲浮家镜水间。\n越女繇来天下白，凭君寄语苎萝山。","英雄泪尽此刀环，我欲浮家镜水间。\n越女繇来天下白，凭君寄语苧萝山。"],["长忆西湖歌采菱，六桥秋水涨渔罾。\n逢君急剪松江绢，乞写双峰烟雨凝。",""],["离亭雨雪暮萧萧，换酒无从得紫貂。\n他日相寻君有梦，东樵不在即西樵。",""],["君能中圣复中贤，自可长生作酒仙。\n不见酒星三四五，千秋历历绛河边。",""],["天上依然揽玉珂，人间不复画青蛾。\n而今却羡双星好，犹得年年一渡河。",""],["三川水落限门长，秋色苍苍接越裳。\n海月明时拾海月，人人素足白如霜。",""],["不见仙人驾石船，鉴江秋水正连天。\n石篙撑折三千尺，愁绝蓬莱路渺然。",""],["父子捐身百战时，魂随少帝入天池。\n潘州忠烈推潘氏，一片莓苔蚀旧碑。",""],["北向金陵哭旧君，天生忠义在斯文。\n一师六弟祠宫在，正气苍茫接白云。",""],["幸蜀当年扈六龙，凄凉故宅草全封。\n心伤二帝馀遗诏，泣向三泉见御容。",""],["观山近接下宫湾，一棹烟波向夕闲。\n玉井流从金井出，朝霞飞作暮霞还。","观山近接下宫湾，一棹烟波向夕閒。\n玉井流从金井出，朝霞飞作暮霞还。"],["宝山春色照珠台，中有龙湫万壑回。\n父老时时望苍翠，麖鸣知有赦书来。",""],["蜃气苍茫望欲无，天边一道限门孤。\n蚌含明月浮沧海，珠鳖江中亦吐珠。",""],["孔雀花时金翠多，自怜文采舞婆娑。\n珠毛向夕无楼处，飞向人间触网罗。",""],["南巴城下绕江流，二广山川此上游。\n天险可怜资敌国，更无冯盎出潘州。",""],["不用仙人绿玉筇，朱明门户水重重。\n因君识得香溪路，舟入罗浮四百峰。",""],["三日仙源路不穷，冲虚观口系孤篷。\n自来渔父无寻处，曲曲千岩万壑中。",""],["棹入芙蓉路尽迷，虚传七十二长溪。\n君非五色仙禽引，定是双鬟玉女携。",""],["罗阳一水从丫髻，云母双溪自凤冈。\n此道香溪百馀里，山灵为尔辟鸿荒。",""],["太白当年旌九子，翁山今日命香溪。\n君今名与香溪著，莫惜罗浮白首栖。",""],["当年设帨雁门关，代北诸军尽解颜。\n共道榆林飞将种，明驼莫载木兰还。",""],["我怜堂上有慈姑，老凤啾啾喜弄雏。\n得此左思娇女子，堪令白发日欢娱。",""],["汝母秦人父越人，汝生于代紫河滨。\n万里三人成骨肉，三年一旦作埃尘。",""],["初生一月即南征，历尽龙沙紫塞城。\n九月霜花凝绣褓，苦寒不断有啼声。",""],["祖母欢分一味甘，时时枣栗满花篮。\n殷勤剪发为双髴，更与炎洲翡翠簪。",""],["两龄失恃汝何知，哭向桐棺索乳时。\n万里将来孩抱物，何人见尔不生悲。",""],["孩笑朝朝绣佛前，那知有母在黄泉。\n殷勤赖有楼烦女，似燕将雏得两年。",""],["朝弄书篇夕画图，聪明不独识之无。\n女中博士吾真望，不比寻常掌上珠。",""],["频同曹子伤金瓠，不共任妻哭泽兰。\n汝母劬劳应未足，九泉相待共饥寒。",""],["三月艰难瘴海行，归来不见一枝琼。\n家中大小相持哭，尽作哀猿肠断声。",""],["四十商瞿未有儿，初生一女不曾悲。\n三年鞠育何辛苦，作母多于作父时。",""],["空留汝母嫁时衣，雾縠花罗香渐微。\n欲与他人今不忍，华山高处瘗斜晖。",""],["罗浮亦作衣冠冢，令化麻姑蝴蝶飞。\n留与人呼小凤子，文章五色有光辉。",""],["阿母桐花儿小凤，桐花小凤命相关。\n羽毛未就花先死，凤自无心在世间。",""],["汝母泉台久寂寥，香魂应念女儿娇。\n月中顾兔难离腹，风里杨花易失条。",""],["无端母子来烟瘴，送却浮生数月中。\n无母不应还有子，芙蓉蒂断易随风。",""],["暂到人间未四秋，为谁辛苦作蜉蝣。\n朝生暮死非予罪，哭向皇天泪迸流。",""],["葬汝先人墓道西，白杨多处作幽闺。\n若知汝父长相忆，莫向黄泉汝母啼。",""],["母子之思水月同，月轮只在水当中。\n汝今母子重相见，须识灵光一片空。",""],["三闾相见定相亲，颂尔芳辞艳绝伦。\n暮采兰英朝采菊，从来好色一骚人。",""],["餐来五内金沙发，自是丹砂世不知。\n却笑晋时勾漏令，求仙不解种荔枝。",""],["摘来先饲小鹦哥，万颗匀圆裹芰荷。\n娇女堂前争不已，侍儿花底斗谁多。",""],["月中不辨赤瑛盘，笑揽飞琼仔细看。\n君欲身轻成大药，莫辞多啮女唇丹。",""],["一朵红酥被酒馀，笑从掌上解绡裾。\n丰肌欲拊难留手，乍比凝脂尚不如。",""],["摘来经宿尤甜美，日气全消色尚丹。\n一片冰霜凝火实，正阳津液吸来寒。",""],["新梳宝髻牡丹松，旧染绫襦荔子同。\n金钏换来媚夫婿，一盘都是状元红。",""],["小姬生日喜含春，绣佛堂前百果陈。\n三爵奉卿何所祝，玉颜长似荔枝新。",""],["沉香浦口万枝悬，鹤顶葳蕤浥露鲜。\n浣女憨妆人共笑，和花插在髻鬟边。",""],["琵琶洲畔卖花船，溪女娇娆工数钱。\n玉腕罗裙摇橹至，荔支擎出与红莲。",""],["流花桥上踏春还，回首荣华薤露间。\n一片冰心堪内映，宁愁时俗薄朱颜。",""],["少小嬉游向狭邪，容颜如日映丹霞。\n荔支不用金钱买，自有佳人掷满车。",""],["水枝未尽复山枝，自上枝头摘不迟。\n多食不须忧折福，殷勤为作荔支辞。",""],["何来一队绿罗裳，花渡头前弄晚妆。\n欲结同心无所有，怀中大小总丁香。",""],["入口甜霜一片消，美人含吐与琼瑶。\n不愁多食中生热，更有梅花蜜可调。",""],["情深草木奈君何，欲补荔支入九歌。\n异日兰台诸弟子，招魂须用柘浆多。",""],["收香么凤是前身，又作焚香小玉人。\n此去琼南众香国，水沉多买奉仙真。",""],["怜尔朝朝向绣床，只薰东莞女儿香。\n琼州为买奇南去，不惜天风接海长。",""],["花田昔作花农去，香市今成香估来。\n黎女定多油速好，金钱数数笑颜开。",""],["生本珠娘不爱珠，每将明月换香榆。\n绣成天女兼毛女，沉水多薰取自娱。",""],["多栽香子傍芙蓉，家有香田即素封。\n欲向东官金桔岭，尽将妻子作香农。",""],["惨淡龙颜向六军，马嵬山下血沾裙。\n当时何不弃天子，直抱瑶妃入白云。",""],["内湖水暖外湖寒，看杀鸳鸯忘钓竿。\n一叶一花都弄遍，月明还向大夫滩。",""],["几朵芙蓉雨外分，麻姑玉女翠氤氲。\n青青一髻无多雪，日夕光含一片云。",""],["化鹤卢耽去几年，蜉蝣衣服已成烟。\n羚羊峡口君休去，柯烂归来未是仙。",""],["丁丁我亦一山樵，斤斧秋来日在腰。\n欲作仙人棋弟子，芝房赌取董仁娇。",""],["碧玉相思君已深，双莲且寄一枝簪。\n不愁叶底无甜藕，只要花中有苦心。",""],["树树穿榕是木棉，人家多在海门边。\n初晴雨气犹含日，乍暖春阴尚作烟。",""],["不将■鬌学中华，亦有胭脂似汉家。\n一自明妃天上落，春光留得在龙沙。",""],["多饮酡酥玉貌红，盘头大脚出辽宫。\n生憎走马穿花去，更打鸳鸯一弹弓。",""],["筝琶近得教坊师，尽学金元杂剧词。\n小唱最嫌时曲贱，此音惟有顿仁知。",""],["一片湖山是塞沙，招魂只用一声笳。\n魂兮解向阴阳食，不必清明奠乳茶。",""],["南北湖干尽白坟，笳声催去哭边云。\n满州兵妇衣如雪，一半红妆学汉军。",""],["枝枝都被晓风催，岂有黄莺啄复开。\n已是落花花已落，何须吹去复吹来。",""],["生作芙蓉即断肠，蘼芜可幸不曾香。\n青青青到天涯路，一片惟知惹夕阳。",""],["花前小立影徘徊，风解吹裙百折开。\n已有泪光同白露，不须明月上衣来。","花前小立影徘徊，风解吹裙百摺开。\n已有泪光同白露，不须明月上衣来。"],["扫镜青衣亦自妍，相逢正及破瓜前。\n人言白白泥中藕，却胜红红水上莲。",""],["新眉懒画月斜斜，调粉无心注露华。\n解道海棠因泪化，莫教沾洒又生花。",""],["白酪黄羊捧御娥，貂房半在独峰驼。\n阏氏本是天公主，耳坠金环一倍多。",""],["墩夹边墙内外长，纷纷庐落绕牛羊。\n白貂绿马边头贵，争换红盐向市场。",""],["连墩勾堡雁门西，白麦青稞出未齐。\n边女尽能蒙古语，汉儿多作女真啼。",""],["鸳鸯泺上洗妆多，毛锦团铺向芰荷。\n宫女双凫教仰中，放鹞还去打天鹅。",""],["白马牦牛小种多，新降教负羽林戈。\n天寒围猎乘风雪，两两横吹一海螺。","白马氂牛小种多，新降教负羽林戈。\n天寒围猎乘风雪，两两横吹一海螺。"],["清明争插白杨毛，柏叶双簪出鬓高。\n齐上野坟还较射，妇人偏解中秋毫。",""],["腐肉城南久作尘，忠魂十万委黄巾。\n每逢佳节榆中哭，寒食哀声更感人。",""],["春时即是竹秋时，雨过鞭行更不迟。\n种向西南成笋易，求鱼待取最柔枝。",""],["扶竹枝枝亦合欢，美人持赠拟琅玕。\n扶桑两两花相比，更采芬馨满玉盘。",""],["西田春夏土膏多，一岁栽蔬一岁禾。\n安得农桑来此地，更租塘水种菱荷。",""],["茨菰冬种夏芙蕖，茭白菱红卖有馀。\n玉溆金塘连十里，鱼花多放当园蔬。",""],["瓜菜西园最有名，芳华苑外野田平。\n菱香藕脆家家有，粳稻花吹暑气清。",""],["斜阳十里尽钟声，兰若相连直接城。\n农圃有僧能食力，露葵香处笑逢迎。",""],["西禅古寺枕龟峰，东接浮丘暮霭重。\n少小撒金仙巷住，先人精舍傍芙蓉。",""],["白头卖食市门边，手执诗书不数钱。\n舂赁更教人不识，要离地下解相怜。",""],["词赋场中最老师，都门友教遍诸旗。\n满洲弟子公卿辈，一一参貂献不迟。",""],["客死淮南无故人，一棺江上屡迷津。\n囊中文草知多少，化作芦花满水滨。",""],["梅里相知汝最深，鸯湖朱十亦同心。\n平生唱和如胶漆，忍隔黄泉泪满襟。",""],["生憎芍药是将离，数寄干归归故迟。\n多捣蛇床作香沐，郎丹更与菟丝宜。","生憎芍药是将离，数寄乾归归故迟。\n多捣蛇床作香沐，郎丹更与菟丝宜。"],["罗浮翠羽日啾啾，饱食梅花亦复愁。\n不见美人来树下，月明寒作泪光流。",""],["纷纷幺凤向瑶华，收尽香烟不似花。\n绿萼一株餐不尽，衔将数片过东家。",""],["青溪一片长蘼芜，天上张星作小姑。\n小像沉香薰未已，夷光得似丽华无。",""],["胭脂井里殉君王，花作陈宫二女香。\n谁道小姑人不识，美人张孔两鸳鸯。",""],["青溪一道秦淮接，桃叶桃根总在兹。\n六代风流归此地，何人不拜女郎祠。",""],["频年失志卧林丘，正赖佳人慰四愁。\n欲写三闾哀怨曲，今无丽玉引箜篌。",""],["玉琴空怨雉朝飞，岁晚吴门生计微。\n庑下无人来馈食，堂前有母为缝衣。",""],["零落香魂去不回，黄泉应上望夫台。\n他生不愿为夫妇，但作罗浮蛱蝶来。",""],["将军贶室怜清苦，玉帛还劳子大夫。\n多谢寓公言好结，千秋嘉耦一朝无。",""],["频辞板屋从君子，自是秦风爱德音。\n我有西戎征战志，小戎日夕为君吟。",""],["明星玉女羡乘龙，白帝为媒得彼秾。\n一自丈夫毛女合，华山今有丈人峰。",""],["将军战败斩旌旗，身作长城控月氏。\n夜半鼓声寒不起，可怜冰上弃孤儿。",""],["三秋苦战在黄沙，血作胭脂山上花。\n孝有曹娥曾弗子，忠如去病不为家。",""],["来时哭度雁门关，酹酒明妃白草间。\n胡越可怜俱远嫁，梦魂空逐雁飞还。",""],["八月风高放角鹰，行行游猎十三陵。\n随夫北岳攀阴雪，抱子桑干履薄冰。","八月风高放角鹰，行行游猎十三陵。\n随夫北岳攀阴雪，抱子桑乾履薄冰。"],["一鞭朝出纥真束，花颔娇嘶万里风。\n忆向阏氏营上过，蛮姬争进乳茶红。",""],["九月云中道路难，雪花如掌打征鞍。\n可怜生女方弥月，使出兰闺犯岁寒。",""],["娘子城边忆打围，鸾靴上马疾如飞。\n儿夫不忍弯弓射，心爱双双白兔肥。",""]]});
